DECLARE manifest jsonb:='[{"name":"202609240001_initial.sql","sql":"-- Private application schema. Browser Supabase clients have no clinical table access.\nCREATE SCHEMA IF NOT EXISTS mymind;\nSET LOCAL search_path TO mymind, public;\nCREATE TABLE IF NOT EXISTS usuarios (\n  id TEXT PRIMARY KEY NOT NULL,\n  email TEXT NOT NULL UNIQUE,\n  password_hash TEXT NOT NULL,\n  rol TEXT NOT NULL DEFAULT ''psicologo'' CHECK (rol IN (''psicologo'', ''administrador'')),\n  nombre TEXT NOT NULL,\n  especialidad TEXT NOT NULL DEFAULT '''',\n  tono TEXT NOT NULL DEFAULT ''Empático'' CHECK (tono IN (''Empático'', ''Educativo'', ''Clínico/Divulgativo'')),\n  enlace_consulta TEXT NOT NULL DEFAULT '''',\n  creado_en TIMESTAMPTZ NOT NULL DEFAULT (now())\n);\n\n\nCREATE TABLE IF NOT EXISTS pacientes (\n  id TEXT PRIMARY KEY NOT NULL DEFAULT (gen_random_uuid()::text),\n  nombre_completo TEXT NOT NULL CHECK (length(trim(nombre_completo)) > 0),\n  email TEXT,\n  telefono TEXT,\n  estado TEXT NOT NULL DEFAULT ''Nuevo contacto''\n    CHECK (estado IN (''Nuevo contacto'', ''En evaluación'', ''Tratamiento activo'', ''Inactivo'')),\n  motivo_consulta TEXT,\n  fecha_registro TIMESTAMPTZ NOT NULL DEFAULT (now()),\n  notas_confidenciales TEXT,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id),\n  fuente_captacion TEXT NOT NULL DEFAULT ''Registro manual''\n);\n\nCREATE TABLE IF NOT EXISTS sesiones (\n  id TEXT PRIMARY KEY NOT NULL DEFAULT (gen_random_uuid()::text),\n  paciente_id TEXT NOT NULL REFERENCES pacientes(id) ON DELETE RESTRICT,\n  fecha_hora TIMESTAMPTZ NOT NULL,\n  estado_sesion TEXT NOT NULL DEFAULT ''Programada''\n    CHECK (estado_sesion IN (''Programada'', ''Realizada'', ''Cancelada'')),\n  duracion_minutos INTEGER NOT NULL DEFAULT 50 CHECK (duracion_minutos BETWEEN 5 AND 480),\n  modalidad TEXT NOT NULL DEFAULT ''Presencial'' CHECK (modalidad IN (''Presencial'', ''Online'')),\n  notas_evolucion TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_pacientes_estado ON pacientes(estado);\nCREATE INDEX IF NOT EXISTS idx_sesiones_paciente_fecha ON sesiones(paciente_id, fecha_hora);\nCREATE INDEX IF NOT EXISTS idx_sesiones_fecha ON sesiones(fecha_hora);\n\nCREATE TABLE IF NOT EXISTS auth_sessions (\n  token_hash TEXT PRIMARY KEY NOT NULL,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,\n  expires_at BIGINT NOT NULL\n);\nCREATE INDEX IF NOT EXISTS idx_auth_expiration ON auth_sessions(expires_at);\nCREATE TABLE IF NOT EXISTS rate_limits (\n  clave TEXT PRIMARY KEY NOT NULL,\n  intentos INTEGER NOT NULL,\n  reinicio BIGINT NOT NULL\n);\nCREATE TABLE IF NOT EXISTS plantillas (\n  id TEXT PRIMARY KEY NOT NULL,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id),\n  nombre TEXT NOT NULL,\n  categoria TEXT NOT NULL,\n  paso INTEGER NOT NULL DEFAULT 1,\n  dias_espera INTEGER NOT NULL DEFAULT 0,\n  asunto TEXT NOT NULL,\n  contenido TEXT NOT NULL,\n  UNIQUE(usuario_id, categoria, paso)\n);\nCREATE TABLE IF NOT EXISTS lead_magnets (\n  id TEXT PRIMARY KEY NOT NULL,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id),\n  titulo TEXT NOT NULL,\n  descripcion TEXT NOT NULL,\n  tipo TEXT NOT NULL CHECK (tipo IN (''guia'', ''test'')),\n  contenido TEXT NOT NULL,\n  preguntas TEXT NOT NULL DEFAULT ''[]'',\n  publicado INTEGER NOT NULL DEFAULT 0 CHECK (publicado IN (0, 1)),\n  creado_en TIMESTAMPTZ NOT NULL DEFAULT (now())\n);\nCREATE INDEX IF NOT EXISTS idx_lead_owner ON lead_magnets(usuario_id);\nCREATE TABLE IF NOT EXISTS captaciones (\n  id TEXT PRIMARY KEY NOT NULL,\n  magnet_id TEXT NOT NULL REFERENCES lead_magnets(id),\n  paciente_id TEXT NOT NULL REFERENCES pacientes(id),\n  consentimiento_contacto INTEGER NOT NULL CHECK (consentimiento_contacto = 1),\n  consentimiento_marketing INTEGER NOT NULL DEFAULT 0 CHECK (consentimiento_marketing IN (0, 1)),\n  texto_consentimiento TEXT NOT NULL,\n  creado_en TIMESTAMPTZ NOT NULL DEFAULT (now()),\n  UNIQUE(magnet_id, paciente_id)\n);\nCREATE TABLE IF NOT EXISTS setup_tokens (\n  token_hash TEXT PRIMARY KEY NOT NULL,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE,\n  expires_at BIGINT NOT NULL\n);\nCREATE TABLE IF NOT EXISTS configuracion_sitio (\n  id INTEGER PRIMARY KEY CHECK (id = 1),\n  profesional_id TEXT NOT NULL REFERENCES usuarios(id),\n  zona_horaria TEXT NOT NULL DEFAULT ''America/Santiago''\n);\nCREATE TABLE IF NOT EXISTS disponibilidad_publica (\n  id TEXT PRIMARY KEY NOT NULL,\n  usuario_id TEXT NOT NULL REFERENCES usuarios(id),\n  fecha_hora TIMESTAMPTZ NOT NULL,\n  duracion_minutos INTEGER NOT NULL CHECK (duracion_minutos BETWEEN 5 AND 480),\n  modalidad TEXT NOT NULL CHECK (modalidad IN (''Presencial'', ''Online'', ''Ambas'')),\n  regla_version INTEGER NOT NULL DEFAULT 0,\n  publicado INTEGER NOT NULL DEFAULT 1 CHECK (publicado IN (0, 1)),\n  sesion_id TEXT UNIQUE REFERENCES sesiones(id),\n  UNIQUE(usuario_id, fecha_hora)\n);\nCREATE INDEX IF NOT EXISTS idx_disponibilidad_owner ON disponibilidad_publica(usuario_id, fecha_hora);\nCREATE TABLE IF NOT EXISTS reservas_publicas (\n  id TEXT PRIMARY KEY NOT NULL,\n  disponibilidad_id TEXT NOT NULL REFERENCES disponibilidad_publica(id),\n  sesion_id TEXT NOT NULL UNIQUE REFERENCES sesiones(id),\n  consentimiento TEXT NOT NULL,\n  creado_en TIMESTAMPTZ NOT NULL DEFAULT (now())\n);\n\nCREATE TABLE IF NOT EXISTS reglas_disponibilidad (\n  usuario_id TEXT PRIMARY KEY REFERENCES usuarios(id),\n  dias TEXT NOT NULL DEFAULT ''[1,2,3,4,5]'',\n  hora_inicio TEXT NOT NULL DEFAULT ''09:00'',\n  hora_fin TEXT NOT NULL DEFAULT ''18:00'',\n  duracion_minutos INTEGER NOT NULL DEFAULT 50,\n  modalidad TEXT NOT NULL DEFAULT ''Ambas'',\n  activa INTEGER NOT NULL DEFAULT 1,\n  version INTEGER NOT NULL DEFAULT 1,\n  generado_dia TEXT NOT NULL DEFAULT ''''\n);\n\n\nCREATE UNIQUE INDEX IF NOT EXISTS usuarios_email_lower ON usuarios(lower(email));\nCREATE INDEX IF NOT EXISTS idx_paciente_owner ON pacientes(usuario_id, estado);\nCREATE INDEX IF NOT EXISTS idx_paciente_owner_email ON pacientes(usuario_id, email);\nCREATE OR REPLACE FUNCTION mymind.keep_patient_owner() RETURNS trigger LANGUAGE plpgsql SET search_path = mymind, pg_temp AS $$\nBEGIN\n  IF OLD.usuario_id IS DISTINCT FROM NEW.usuario_id THEN\n    RAISE EXCEPTION ''Patient owner cannot change'' USING ERRCODE = ''23514'';\n  END IF;\n  RETURN NEW;\nEND $$;\nDROP TRIGGER IF EXISTS paciente_owner_immutable ON pacientes;\nCREATE TRIGGER paciente_owner_immutable BEFORE UPDATE OF usuario_id ON pacientes FOR EACH ROW EXECUTE FUNCTION mymind.keep_patient_owner();\nREVOKE ALL ON SCHEMA mymind FROM PUBLIC;\nREVOKE ALL ON ALL TABLES IN SCHEMA mymind FROM PUBLIC;\nREVOKE ALL ON ALL FUNCTIONS IN SCHEMA mymind FROM PUBLIC;\nDO $$ DECLARE r record; role_name text; BEGIN\n  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = ''mymind'' LOOP\n    EXECUTE format(''ALTER TABLE mymind.%I ENABLE ROW LEVEL SECURITY'', r.tablename);\n  END LOOP;\n  FOREACH role_name IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN\n      EXECUTE format(''REVOKE ALL ON SCHEMA mymind FROM %I'', role_name);\n      EXECUTE format(''REVOKE ALL ON ALL TABLES IN SCHEMA mymind FROM %I'', role_name);\n      EXECUTE format(''REVOKE ALL ON ALL FUNCTIONS IN SCHEMA mymind FROM %I'', role_name);\n    END IF;\n  END LOOP;\nEND $$;\n","version":"202609240001","label":"initial","checksum":"4aef40c547ae306cd1526db04a89fb7912af9a94d601fbaea8f4779e90b8b285","legacy":"5a1e84117420d734c196e13b6ba19695cfdba961f2a87a9615b3500167d2b29e","tokens":"CREATE\u001fSCHEMA\u001fIF\u001fNOT\u001fEXISTS\u001fmymind\u001fSET\u001fLOCAL\u001fsearch_path\u001fTO\u001fmymind\u001f,\u001fpublic\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fusuarios\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001femail\u001fTEXT\u001fNOT\u001fNULL\u001fUNIQUE\u001f,\u001fpassword_hash\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001frol\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''psicologo''\u001fCHECK\u001f(\u001frol\u001fIN\u001f(\u001f''psicologo''\u001f,\u001f''administrador''\u001f)\u001f)\u001f,\u001fnombre\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fespecialidad\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''''\u001f,\u001ftono\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Empático''\u001fCHECK\u001f(\u001ftono\u001fIN\u001f(\u001f''Empático''\u001f,\u001f''Educativo''\u001f,\u001f''Clínico/Divulgativo''\u001f)\u001f)\u001f,\u001fenlace_consulta\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''''\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fnow\u001f(\u001f)\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fpacientes\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fgen_random_uuid\u001f(\u001f)\u001f:\u001f:\u001ftext\u001f)\u001f,\u001fnombre_completo\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001flength\u001f(\u001ftrim\u001f(\u001fnombre_completo\u001f)\u001f)\u001f>\u001f0\u001f)\u001f,\u001femail\u001fTEXT\u001f,\u001ftelefono\u001fTEXT\u001f,\u001festado\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Nuevo contacto''\u001fCHECK\u001f(\u001festado\u001fIN\u001f(\u001f''Nuevo contacto''\u001f,\u001f''En evaluación''\u001f,\u001f''Tratamiento activo''\u001f,\u001f''Inactivo''\u001f)\u001f)\u001f,\u001fmotivo_consulta\u001fTEXT\u001f,\u001ffecha_registro\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fnow\u001f(\u001f)\u001f)\u001f,\u001fnotas_confidenciales\u001fTEXT\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001ffuente_captacion\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Registro manual''\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fsesiones\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fgen_random_uuid\u001f(\u001f)\u001f:\u001f:\u001ftext\u001f)\u001f,\u001fpaciente_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fpacientes\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001ffecha_hora\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001festado_sesion\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Programada''\u001fCHECK\u001f(\u001festado_sesion\u001fIN\u001f(\u001f''Programada''\u001f,\u001f''Realizada''\u001f,\u001f''Cancelada''\u001f)\u001f)\u001f,\u001fduracion_minutos\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f5\u001f0\u001fCHECK\u001f(\u001fduracion_minutos\u001fBETWEEN\u001f5\u001fAND\u001f4\u001f8\u001f0\u001f)\u001f,\u001fmodalidad\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Presencial''\u001fCHECK\u001f(\u001fmodalidad\u001fIN\u001f(\u001f''Presencial''\u001f,\u001f''Online''\u001f)\u001f)\u001f,\u001fnotas_evolucion\u001fTEXT\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_pacientes_estado\u001fON\u001fpacientes\u001f(\u001festado\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_sesiones_paciente_fecha\u001fON\u001fsesiones\u001f(\u001fpaciente_id\u001f,\u001ffecha_hora\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_sesiones_fecha\u001fON\u001fsesiones\u001f(\u001ffecha_hora\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fauth_sessions\u001f(\u001ftoken_hash\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001fexpires_at\u001fBIGINT\u001fNOT\u001fNULL\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_auth_expiration\u001fON\u001fauth_sessions\u001f(\u001fexpires_at\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001frate_limits\u001f(\u001fclave\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fintentos\u001fINTEGER\u001fNOT\u001fNULL\u001f,\u001freinicio\u001fBIGINT\u001fNOT\u001fNULL\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fplantillas\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fnombre\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fcategoria\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fpaso\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001f,\u001fdias_espera\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001f,\u001fasunto\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fcontenido\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fUNIQUE\u001f(\u001fusuario_id\u001f,\u001fcategoria\u001f,\u001fpaso\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001flead_magnets\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001ftitulo\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fdescripcion\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001ftipo\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001ftipo\u001fIN\u001f(\u001f''guia''\u001f,\u001f''test''\u001f)\u001f)\u001f,\u001fcontenido\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fpreguntas\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''[]''\u001f,\u001fpublicado\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001fCHECK\u001f(\u001fpublicado\u001fIN\u001f(\u001f0\u001f,\u001f1\u001f)\u001f)\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fnow\u001f(\u001f)\u001f)\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_lead_owner\u001fON\u001flead_magnets\u001f(\u001fusuario_id\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fcaptaciones\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fmagnet_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001flead_magnets\u001f(\u001fid\u001f)\u001f,\u001fpaciente_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fpacientes\u001f(\u001fid\u001f)\u001f,\u001fconsentimiento_contacto\u001fINTEGER\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001fconsentimiento_contacto\u001f=\u001f1\u001f)\u001f,\u001fconsentimiento_marketing\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001fCHECK\u001f(\u001fconsentimiento_marketing\u001fIN\u001f(\u001f0\u001f,\u001f1\u001f)\u001f)\u001f,\u001ftexto_consentimiento\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fnow\u001f(\u001f)\u001f)\u001f,\u001fUNIQUE\u001f(\u001fmagnet_id\u001f,\u001fpaciente_id\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fsetup_tokens\u001f(\u001ftoken_hash\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001fexpires_at\u001fBIGINT\u001fNOT\u001fNULL\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fconfiguracion_sitio\u001f(\u001fid\u001fINTEGER\u001fPRIMARY\u001fKEY\u001fCHECK\u001f(\u001fid\u001f=\u001f1\u001f)\u001f,\u001fprofesional_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fzona_horaria\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''America/Santiago''\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fdisponibilidad_publica\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001ffecha_hora\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001fduracion_minutos\u001fINTEGER\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001fduracion_minutos\u001fBETWEEN\u001f5\u001fAND\u001f4\u001f8\u001f0\u001f)\u001f,\u001fmodalidad\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001fmodalidad\u001fIN\u001f(\u001f''Presencial''\u001f,\u001f''Online''\u001f,\u001f''Ambas''\u001f)\u001f)\u001f,\u001fregla_version\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001f,\u001fpublicado\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001fCHECK\u001f(\u001fpublicado\u001fIN\u001f(\u001f0\u001f,\u001f1\u001f)\u001f)\u001f,\u001fsesion_id\u001fTEXT\u001fUNIQUE\u001fREFERENCES\u001fsesiones\u001f(\u001fid\u001f)\u001f,\u001fUNIQUE\u001f(\u001fusuario_id\u001f,\u001ffecha_hora\u001f)\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_disponibilidad_owner\u001fON\u001fdisponibilidad_publica\u001f(\u001fusuario_id\u001f,\u001ffecha_hora\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001freservas_publicas\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fNOT\u001fNULL\u001f,\u001fdisponibilidad_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fdisponibilidad_publica\u001f(\u001fid\u001f)\u001f,\u001fsesion_id\u001fTEXT\u001fNOT\u001fNULL\u001fUNIQUE\u001fREFERENCES\u001fsesiones\u001f(\u001fid\u001f)\u001f,\u001fconsentimiento\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001f(\u001fnow\u001f(\u001f)\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001freglas_disponibilidad\u001f(\u001fusuario_id\u001fTEXT\u001fPRIMARY\u001fKEY\u001fREFERENCES\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fdias\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''[1,2,3,4,5]''\u001f,\u001fhora_inicio\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''09:00''\u001f,\u001fhora_fin\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''18:00''\u001f,\u001fduracion_minutos\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f5\u001f0\u001f,\u001fmodalidad\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''Ambas''\u001f,\u001factiva\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001f,\u001fversion\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001f,\u001fgenerado_dia\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''''\u001f)\u001fCREATE\u001fUNIQUE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fusuarios_email_lower\u001fON\u001fusuarios\u001f(\u001flower\u001f(\u001femail\u001f)\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_paciente_owner\u001fON\u001fpacientes\u001f(\u001fusuario_id\u001f,\u001festado\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_paciente_owner_email\u001fON\u001fpacientes\u001f(\u001fusuario_id\u001f,\u001femail\u001f)\u001fCREATE\u001fOR\u001fREPLACE\u001fFUNCTION\u001fmymind\u001f.\u001fkeep_patient_owner\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n  IF OLD.usuario_id IS DISTINCT FROM NEW.usuario_id THEN\n    RAISE EXCEPTION ''Patient owner cannot change'' USING ERRCODE = ''23514'';\n  END IF;\n  RETURN NEW;\nEND $$\u001fDROP\u001fTRIGGER\u001fIF\u001fEXISTS\u001fpaciente_owner_immutable\u001fON\u001fpacientes\u001fCREATE\u001fTRIGGER\u001fpaciente_owner_immutable\u001fBEFORE\u001fUPDATE\u001fOF\u001fusuario_id\u001fON\u001fpacientes\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fkeep_patient_owner\u001f(\u001f)\u001fREVOKE\u001fALL\u001fON\u001fSCHEMA\u001fmymind\u001fFROM\u001fPUBLIC\u001fREVOKE\u001fALL\u001fON\u001fALL\u001fTABLES\u001fIN\u001fSCHEMA\u001fmymind\u001fFROM\u001fPUBLIC\u001fREVOKE\u001fALL\u001fON\u001fALL\u001fFUNCTIONS\u001fIN\u001fSCHEMA\u001fmymind\u001fFROM\u001fPUBLIC\u001fDO\u001f$$ DECLARE r record; role_name text; BEGIN\n  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = ''mymind'' LOOP\n    EXECUTE format(''ALTER TABLE mymind.%I ENABLE ROW LEVEL SECURITY'', r.tablename);\n  END LOOP;\n  FOREACH role_name IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN\n      EXECUTE format(''REVOKE ALL ON SCHEMA mymind FROM %I'', role_name);\n      EXECUTE format(''REVOKE ALL ON ALL TABLES IN SCHEMA mymind FROM %I'', role_name);\n      EXECUTE format(''REVOKE ALL ON ALL FUNCTIONS IN SCHEMA mymind FROM %I'', role_name);\n    END IF;\n  END LOOP;\nEND $$","contract":[["column:usuarios.id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:usuarios.email","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:usuarios.password_hash","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:usuarios.rol","{\"type\": \"text\", \"default\": \"''psicologo''::text\", \"required\": true}"],["column:usuarios.nombre","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:usuarios.especialidad","{\"type\": \"text\", \"default\": \"''''::text\", \"required\": true}"],["column:usuarios.tono","{\"type\": \"text\", \"default\": \"''Empático''::text\", \"required\": true}"],["column:usuarios.enlace_consulta","{\"type\": \"text\", \"default\": \"''''::text\", \"required\": true}"],["column:usuarios.creado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:pacientes.id","{\"type\": \"text\", \"default\": \"(gen_random_uuid())::text\", \"required\": true}"],["column:pacientes.nombre_completo","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:pacientes.email","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.telefono","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.estado","{\"type\": \"text\", \"default\": \"''Nuevo contacto''::text\", \"required\": true}"],["column:pacientes.motivo_consulta","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.fecha_registro","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:pacientes.notas_confidenciales","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:pacientes.fuente_captacion","{\"type\": \"text\", \"default\": \"''Registro manual''::text\", \"required\": true}