:sesiones:PRIMARY KEY (id)","present"],["constraint:sesiones:FOREIGN KEY (paciente_id) REFERENCES mymind.pacientes(id) ON DELETE RESTRICT","present"],["constraint:auth_sessions:PRIMARY KEY (token_hash)","present"],["constraint:rate_limits:PRIMARY KEY (clave)","present"],["constraint:plantillas:PRIMARY KEY (id)","present"],["constraint:plantillas:UNIQUE (usuario_id, categoria, paso)","present"],["constraint:plantillas:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id)","present"],["constraint:lead_magnets:CHECK ((tipo = ANY (ARRAY[''guia''::text, ''test''::text])))","present"],["constraint:lead_magnets:CHECK ((publicado = ANY (ARRAY[0, 1])))","present"],["constraint:lead_magnets:PRIMARY KEY (id)","present"],["constraint:lead_magnets:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id)","present"],["constraint:captaciones:CHECK ((consentimiento_contacto = 1))","present"],["constraint:captaciones:CHECK ((consentimiento_marketing = ANY (ARRAY[0, 1])))","present"],["constraint:captaciones:PRIMARY KEY (id)","present"],["constraint:captaciones:UNIQUE (magnet_id, paciente_id)","present"],["constraint:captaciones:FOREIGN KEY (magnet_id) REFERENCES mymind.lead_magnets(id)","present"],["constraint:captaciones:FOREIGN KEY (paciente_id) REFERENCES mymind.pacientes(id)","present"],["constraint:setup_tokens:PRIMARY KEY (token_hash)","present"],["constraint:setup_tokens:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id) ON DELETE CASCADE","present"],["constraint:configuracion_sitio:CHECK ((id = 1))","present"],["constraint:configuracion_sitio:PRIMARY KEY (id)","present"],["constraint:configuracion_sitio:FOREIGN KEY (profesional_id) REFERENCES mymind.usuarios(id)","present"],["constraint:disponibilidad_publica:CHECK (((duracion_minutos >= 5) AND (duracion_minutos <= 480)))","present"],["constraint:disponibilidad_publica:CHECK ((modalidad = ANY (ARRAY[''Presencial''::text, ''Online''::text, ''Ambas''::text])))","present"],["constraint:disponibilidad_publica:CHECK ((publicado = ANY (ARRAY[0, 1])))","present"],["constraint:disponibilidad_publica:PRIMARY KEY (id)","present"],["constraint:disponibilidad_publica:UNIQUE (sesion_id)","present"],["constraint:disponibilidad_publica:UNIQUE (usuario_id, fecha_hora)","present"],["constraint:disponibilidad_publica:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id)","present"],["constraint:disponibilidad_publica:FOREIGN KEY (sesion_id) REFERENCES mymind.sesiones(id)","present"],["constraint:reservas_publicas:PRIMARY KEY (id)","present"],["constraint:reservas_publicas:UNIQUE (sesion_id)","present"],["constraint:reservas_publicas:FOREIGN KEY (disponibilidad_id) REFERENCES mymind.disponibilidad_publica(id)","present"],["constraint:reservas_publicas:FOREIGN KEY (sesion_id) REFERENCES mymind.sesiones(id)","present"],["constraint:reglas_disponibilidad:PRIMARY KEY (usuario_id)","present"],["constraint:reglas_disponibilidad:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id)","present"],["table:usuarios","{\"rls\": true, \"force\": false}"],["table:pacientes","{\"rls\": true, \"force\": false}"],["table:sesiones","{\"rls\": true, \"force\": false}"],["table:auth_sessions","{\"rls\": true, \"force\": false}"],["table:rate_limits","{\"rls\": true, \"force\": false}"],["table:plantillas","{\"rls\": true, \"force\": false}"],["table:lead_magnets","{\"rls\": true, \"force\": false}"],["table:captaciones","{\"rls\": true, \"force\": false}"],["table:setup_tokens","{\"rls\": true, \"force\": false}"],["table:configuracion_sitio","{\"rls\": true, \"force\": false}"],["table:disponibilidad_publica","{\"rls\": true, \"force\": false}"],["table:reservas_publicas","{\"rls\": true, \"force\": false}"],["table:reglas_disponibilidad","{\"rls\": true, \"force\": false}"],["function:keep_patient_owner()","CREATE OR REPLACE FUNCTION mymind.keep_patient_owner()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n  IF OLD.usuario_id IS DISTINCT FROM NEW.usuario_id THEN\n    RAISE EXCEPTION ''Patient owner cannot change'' USING ERRCODE = ''23514'';\n  END IF;\n  RETURN NEW;\nEND $function$\n"],["trigger:pacientes.paciente_owner_immutable","CREATE TRIGGER paciente_owner_immutable BEFORE UPDATE OF usuario_id ON mymind.pacientes FOR EACH ROW EXECUTE FUNCTION mymind.keep_patient_owner()"],["index:idx_paciente_owner","CREATE INDEX idx_paciente_owner ON mymind.pacientes USING btree (usuario_id, estado)"],["index:idx_disponibilidad_owner","CREATE INDEX idx_disponibilidad_owner ON mymind.disponibilidad_publica USING btree (usuario_id, fecha_hora)"],["index:idx_sesiones_fecha","CREATE INDEX idx_sesiones_fecha ON mymind.sesiones USING btree (fecha_hora)"],["index:idx_sesiones_paciente_fecha","CREATE INDEX idx_sesiones_paciente_fecha ON mymind.sesiones USING btree (paciente_id, fecha_hora)"],["index:idx_paciente_owner_email","CREATE INDEX idx_paciente_owner_email ON mymind.pacientes USING btree (usuario_id, email)"],["index:usuarios_email_lower","CREATE UNIQUE INDEX usuarios_email_lower ON mymind.usuarios USING btree (lower(email))"],["index:idx_lead_owner","CREATE INDEX idx_lead_owner ON mymind.lead_magnets USING btree (usuario_id)"],["index:idx_auth_expiration","CREATE INDEX idx_auth_expiration ON mymind.auth_sessions USING btree (expires_at)"],["index:idx_pacientes_estado","CREATE INDEX idx_pacientes_estado ON mymind.pacientes USING btree (estado)"]]},{"name":"202609250001_patient_archive.sql","sql":"-- Compatible with an existing manually added status column.\nALTER TABLE mymind.pacientes ADD COLUMN IF NOT EXISTS status TEXT DEFAULT ''active'';\nUPDATE mymind.pacientes SET status = ''active'' WHERE status IS NULL;\nALTER TABLE mymind.pacientes ALTER COLUMN status SET DEFAULT ''active'';\nALTER TABLE mymind.pacientes ALTER COLUMN status SET NOT NULL;\nALTER TABLE mymind.pacientes ADD CONSTRAINT pacientes_status_valid CHECK (status IN (''active'', ''archived''));\nCREATE INDEX IF NOT EXISTS idx_pacientes_owner_status ON mymind.pacientes (usuario_id, status, fecha_registro DESC);\n","version":"202609250001","label":"patient_archive","checksum":"c6ec434d5ae359af709835db9718550bc08471a16251e2d222d587699052d93f","legacy":"c21d83bcaa4601a548f8459e8ce1bb873dcb73848ac6cdaa5ba823523a83a90c","tokens":"ALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fstatus\u001fTEXT\u001fDEFAULT\u001f''active''\u001fUPDATE\u001fmymind\u001f.\u001fpacientes\u001fSET\u001fstatus\u001f=\u001f''active''\u001fWHERE\u001fstatus\u001fIS\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fstatus\u001fSET\u001fDEFAULT\u001f''active''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fstatus\u001fSET\u001fNOT\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCONSTRAINT\u001fpacientes_status_valid\u001fCHECK\u001f(\u001fstatus\u001fIN\u001f(\u001f''active''\u001f,\u001f''archived''\u001f)\u001f)\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fidx_pacientes_owner_status\u001fON\u001fmymind\u001f.\u001fpacientes\u001f(\u001fusuario_id\u001f,\u001fstatus\u001f,\u001ffecha_registro\u001fDESC\u001f)","contract":[["column:pacientes.status","{\"type\": \"text\", \"default\": \"''active''::text\", \"required\": true}"],["constraint:pacientes:CHECK ((status = ANY (ARRAY[''active''::text, ''archived''::text])))","present"],["index:idx_pacientes_owner_status","CREATE INDEX idx_pacientes_owner_status ON mymind.pacientes USING btree (usuario_id, status, fecha_registro DESC)"]]},{"name":"202610190001_agenda_integrations.sql","sql":"ALTER TABLE mymind.usuarios\n ADD COLUMN google_calendar_token TEXT,\n ADD COLUMN sync_enabled BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN recordatorios_email BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN recordatorios_whatsapp BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN recordatorio_horas INTEGER NOT NULL DEFAULT 24 CHECK (recordatorio_horas BETWEEN 1 AND 168);\nCOMMENT ON COLUMN mymind.usuarios.google_calendar_token IS ''Reserved for encrypted OAuth credentials. Never expose through profile APIs.'';\nALTER TABLE mymind.sesiones ADD COLUMN estado_confirmacion TEXT NOT NULL DEFAULT ''pendiente''\n CHECK (estado_confirmacion IN (''pendiente'',''confirmada'',''recordatorio_enviado'',''cancelada''));\nUPDATE mymind.sesiones SET estado_confirmacion=''cancelada'' WHERE estado_sesion=''Cancelada'';\nCREATE TABLE mymind.agenda_emails (\n id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,\n sesion_id TEXT NOT NULL REFERENCES mymind.sesiones(id) ON DELETE CASCADE,\n usuario_id TEXT NOT NULL REFERENCES mymind.usuarios(id) ON DELETE CASCADE,\n fecha_cita TIMESTAMPTZ NOT NULL,\n tipo TEXT NOT NULL CHECK(tipo IN (''confirmacion'',''recordatorio'')),\n destinatario TEXT NOT NULL, modalidad TEXT NOT NULL, zona_horaria TEXT NOT NULL,\n enviar_en TIMESTAMPTZ NOT NULL, creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),\n estado TEXT NOT NULL DEFAULT ''pendiente'' CHECK(estado IN (''pendiente'',''enviado'',''omitido'',''fallido'')),\n intentos INTEGER NOT NULL DEFAULT 0, enviado_en TIMESTAMPTZ,\n UNIQUE(sesion_id,fecha_cita,tipo)\n);\nALTER TABLE mymind.agenda_emails ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON mymind.agenda_emails FROM PUBLIC;\nCREATE INDEX agenda_emails_pending ON mymind.agenda_emails(enviar_en) WHERE estado=''pendiente'';\nCREATE FUNCTION mymind.agenda_state() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF NEW.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''cancelada'';\n ELSIF TG_OP=''UPDATE'' THEN\n  IF NEW.fecha_hora IS DISTINCT FROM OLD.fecha_hora OR OLD.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''pendiente''; END IF;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER agenda_state BEFORE INSERT OR UPDATE OF fecha_hora,estado_sesion ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_state();\nCREATE FUNCTION mymind.agenda_queue_email() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nDECLARE recipient TEXT; owner_id TEXT; enabled BOOLEAN; hours_before INTEGER; zone TEXT;\nBEGIN\n IF NEW.estado_sesion<>''Programada'' OR NEW.fecha_hora<=now() THEN RETURN NEW; END IF;\n SELECT p.email,p.usuario_id,u.recordatorios_email,u.recordatorio_horas,COALESCE(c.zona_horaria,''America/Santiago'')\n INTO recipient,owner_id,enabled,hours_before,zone FROM pacientes p JOIN usuarios u ON u.id=p.usuario_id\n LEFT JOIN configuracion_sitio c ON c.profesional_id=u.id WHERE p.id=NEW.paciente_id;\n IF enabled AND recipient IS NOT NULL AND recipient<>'''' THEN\n INSERT INTO agenda_emails(sesion_id,usuario_id,fecha_cita,tipo,destinatario,modalidad,zona_horaria,enviar_en)\n VALUES (NEW.id,owner_id,NEW.fecha_hora,''confirmacion'',recipient,NEW.modalidad,zone,now()),\n (NEW.id,owner_id,NEW.fecha_hora,''recordatorio'',recipient,NEW.modalidad,zone,GREATEST(now()+interval ''5 minutes'',NEW.fecha_hora-hours_before*interval ''1 hour''))\n ON CONFLICT DO NOTHING;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER agenda_email AFTER INSERT OR UPDATE OF fecha_hora,estado_sesion,modalidad ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_queue_email();\n","version":"202610190001","label":"agenda_integrations","checksum":"63048a3f23e9a08d1abfc3398d514149e793f84fd88918f82853adfdb57108cb","tokens":"ALTER\u001fTABLE\u001fmymind\u001f.\u001fusuarios\u001fADD\u001fCOLUMN\u001fgoogle_calendar_token\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fsync_enabled\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001frecordatorios_email\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001frecordatorios_whatsapp\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001frecordatorio_horas\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f2\u001f4\u001fCHECK\u001f(\u001frecordatorio_horas\u001fBETWEEN\u001f1\u001fAND\u001f1\u001f6\u001f8\u001f)\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fusuarios\u001f.\u001fgoogle_calendar_token\u001fIS\u001f''Reserved for encrypted OAuth credentials. Never expose through profile APIs.''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fsesiones\u001fADD\u001fCOLUMN\u001festado_confirmacion\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''pendiente''\u001fCHECK\u001f(\u001festado_confirmacion\u001fIN\u001f(\u001f''pendiente''\u001f,\u001f''confirmada''\u001f,\u001f''recordatorio_enviado''\u001f,\u001f''cancelada''\u001f)\u001f)\u001fUPDATE\u001fmymind\u001f.\u001fsesiones\u001fSET\u001festado_confirmacion\u001f=\u001f''cancelada''\u001fWHERE\u001festado_sesion\u001f=\u001f''Cancelada''\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fagenda_emails\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fDEFAULT\u001fgen_random_uuid\u001f(\u001f)\u001f:\u001f:\u001ftext\u001f,\u001fsesion_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fsesiones\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001ffecha_cita\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001ftipo\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001ftipo\u001fIN\u001f(\u001f''confirmacion''\u001f,\u001f''recordatorio''\u001f)\u001f)\u001f,\u001fdestinatario\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fmodalidad\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fzona_horaria\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fenviar_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001festado\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''pendiente''\u001fCHECK\u001f(\u001festado\u001fIN\u001f(\u001f''pendiente''\u001f,\u001f''enviado''\u001f,\u001f''omitido''\u001f,\u001f''fallido''\u001f)\u001f)\u001f,\u001fintentos\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001f,\u001fenviado_en\u001fTIMESTAMPTZ\u001f,\u001fUNIQUE\u001f(\u001fsesion_id\u001f,\u001ffecha_cita\u001f,\u001ftipo\u001f)\u001f)\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fagenda_emails\u001fENABLE\u001fROW\u001fLEVEL\u001fSECURITY\u001fREVOKE\u001fALL\u001fON\u001fmymind\u001f.\u001fagenda_emails\u001fFROM\u001fPUBLIC\u001fCREATE\u001fINDEX\u001fagenda_emails_pending\u001fON\u001fmymind\u001f.\u001fagenda_emails\u001f(\u001fenviar_en\u001f)\u001fWHERE\u001festado\u001f=\u001f''pendiente''\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_state\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF NEW.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''cancelada'';\n ELSIF TG_OP=''UPDATE'' THEN\n  IF NEW.fecha_hora IS DISTINCT FROM OLD.fecha_hora OR OLD.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''pendiente''; END IF;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fagenda_state\u001fBEFORE\u001fINSERT\u001fOR\u001fUPDATE\u001fOF\u001ffecha_hora\u001f,\u001festado_sesion\u001fON\u001fmymind\u001f.\u001fsesiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_state\u001f(\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_queue_email\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nDECLARE recipient TEXT; owner_id TEXT; enabled BOOLEAN; hours_before INTEGER; zone TEXT;\nBEGIN\n IF NEW.estado_sesion<>''Programada'' OR NEW.fecha_hora<=now() THEN RETURN NEW; END IF;\n SELECT p.email,p.usuario_id,u.recordatorios_email,u.recordatorio_horas,COALESCE(c.zona_horaria,''America/Santiago'')\n INTO recipient,owner_id,enabled,hours_before,zone FROM pacientes p JOIN usuarios u ON u.id=p.usuario_id\n LEFT JOIN configuracion_sitio c ON c.profesional_id=u.id WHERE p.id=NEW.paciente_id;\n IF enabled AND recipient IS NOT NULL AND recipient<>'''' THEN\n INSERT INTO agenda_emails(sesion_id,usuario_id,fecha_cita,tipo,destinatario,modalidad,zona_horaria,enviar_en)\n VALUES (NEW.id,owner_id,NEW.fecha_hora,''confirmacion'',recipient,NEW.modalidad,zone,now()),\n (NEW.id,owner_id,NEW.fecha_hora,''recordatorio'',recipient,NEW.modalidad,zone,GREATEST(now()+interval ''5 minutes'',NEW.fecha_hora-hours_before*interval ''1 hour''))\n ON CONFLICT DO NOTHING;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fagenda_email\u001fAFTER\u001fINSERT\u001fOR\u001fUPDATE\u001fOF\u001ffecha_hora\u001f,\u001festado_sesion\u001f,\u001fmodalidad\u001fON\u001fmymind\u001f.\u001fsesiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_queue_email\u001f(\u001f)","contract":[["column:sesiones.estado_confirmacion","{\"type\": \"text\", \"default\": \"''pendiente''::text\", \"required\": true}"],["column:usuarios.google_calendar_token","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:usuarios.sync_enabled","{\"type\": \"boolean\", \"default\": \"false\", \"required\": true}"],["column:usuarios.recordatorios_email","{\"type\": \"boolean\", \"default\": \"false\", \"required\": true}"],["column:usuarios.recordatorios_whatsapp","{\"type\": \"boolean\", \"default\": \"false\", \"required\": true}"],["column:usuarios.recordatorio_horas","{\"type\": \"integer\", \"default\": \"24\", \"required\": true}"],["column:agenda_emails.id","{\"type\": \"text\", \"default\": \"(gen_random_uuid())::text\", \"required\": true}"],["column:agenda_emails.sesion_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.fecha_cita","{\"type\": \"timestamp with time zone\", \"default\": null, \"required\": true}"],["column:agenda_emails.tipo","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.destinatario","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.modalidad","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.zona_horaria","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:agenda_emails.enviar_en","{\"type\": \"timestamp with time zone\", \"default\": null, \"required\": true}"],["column:agenda_emails.creado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:agenda_emails.estado","{\"type\": \"text\", \"default\": \"''pendiente''::text\", \"required\": true}"],["column:agenda_emails.intentos","{\"type\": \"integer\", \"default\": \"0\", \"required\": true}"],["column:agenda_emails.enviado_en","{\"type\": \"timestamp with time zone\", \"default\": null, \"required\": false}"],["constraint:usuarios:CHECK (((recordatorio_horas >= 1) AND (recordatorio_horas <= 168)))","present"],["constraint:sesiones:CHECK ((estado_confirmacion = ANY (ARRAY[''pendiente''::text, ''confirmada''::text, ''recordatorio_enviado''::text, ''cancelada''::text])))","present"],["constraint:agenda_emails:CHECK ((tipo = ANY (ARRAY[''confirmacion''::text, ''recordatorio''::text])))","present"],["constraint:agenda_emails:CHECK ((estado = ANY (ARRAY[''pendiente''::text, ''enviado''::text, ''omitido''::text, ''fallido''::text])))","present"],["constraint:agenda_emails:PRIMARY KEY (id)","present"],["constraint:agenda_emails:UNIQUE (sesion_id, fecha_cita, tipo)","present"],["constraint:agenda_emails:FOREIGN KEY (sesion_id) REFERENCES mymind.sesiones(id) ON DELETE CASCADE","present"],["constraint:agenda_emails:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id) ON DELETE CASCADE","present"],["table:agenda_emails","{\"rls\": true, \"force\": false}"],["function:agenda_state()","CREATE OR REPLACE FUNCTION mymind.agenda_state()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n IF NEW.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''cancelada'';\n ELSIF TG_OP=''UPDATE'' THEN\n  IF NEW.fecha_hora IS DISTINCT FROM OLD.fecha_hora OR OLD.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''pendiente''; END IF;\n END IF;\n RETURN NEW;\nEND $function$\n"],["function:agenda_queue_email()","CREATE OR REPLACE FUNCTION mymind.agenda_queue_email()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nDECLARE recipient TEXT; owner_id TEXT; enabled BOOLEAN; hours_before INTEGER; zone TEXT;\nBEGIN\n IF NEW.estado_sesion<>''Programada'' OR NEW.fecha_hora<=now() THEN RETURN NEW; END IF;\n SELECT p.email,p.usuario_id,u.recordatorios_email,u.recordatorio_horas,COALESCE(c.zona_horaria,''America/Santiago'')\n INTO recipient,owner_id,enabled,hours_before,zone FROM pacientes p JOIN usuarios u ON u.id=p.usuario_id\n LEFT JOIN configuracion_sitio c ON c.profesional_id=u.id WHERE p.id=NEW.paciente_id;\n IF enabled AND recipient IS NOT NULL AND recipient<>'''' THEN\n INSERT INTO agenda_emails(sesion_id,usuario_id,fecha_cita,tipo,destinatario,modalidad,zona_horaria,enviar_en)\n VALUES (NEW.id,owner_id,NEW.fecha_hora,''confirmacion'',recipient,NEW.modalidad,zone,now()),\n (NEW.id,owner_id,NEW.fecha_hora,''recordatorio'',recipient,NEW.modalidad,zone,GREATEST(now()+interval ''5 minutes'',NEW.fecha_hora-hours_before*interval ''1 hour''))\n ON CONFLICT DO NOTHING;\n END IF;\n RETURN NEW;\nEND $function$\n"],["trigger:sesiones.agenda_email","CREATE TRIGGER agenda_email AFTER INSERT OR UPDATE OF fecha_hora, estado_sesion, modalidad ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_queue_email()"],["trigger:sesiones.agenda_state","CREATE TRIGGER agenda_state BEFORE INSERT OR UPDATE OF fecha_hora, estado_sesion ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_state()"],["index:agenda_emails_pending","CREATE INDEX agenda_emails_pending ON mymind.agenda_emails USING btree (enviar_en) WHERE (estado = ''pendiente''::text)"]]},{"name":"202610190002_patient_tags.sql","sql":"ALTER TABLE mymind.pacientes ADD COLUMN IF NOT EXISTS etiquetas TEXT[] DEFAULT ARRAY[]::TEXT[];\nUPDATE mymind.pacientes SET etiquetas=ARRAY[]::TEXT[] WHERE etiquetas IS NULL;\nALTER TABLE mymind.pacientes ALTER COLUMN etiquetas SET DEFAULT ARRAY[]::TEXT[];\nALTER TABLE mymind.pacientes ALTER COLUMN etiquetas SET NOT NULL;\nALTER TABLE mymind.pacientes ADD CONSTRAINT pacientes_etiquetas_limit CHECK (cardinality(etiquetas)<=20 AND array_position(etiquetas,NULL) IS NULL);\nCOMMENT ON COLUMN mymind.pacientes.etiquetas IS ''Custom patient labels scoped through usuario_id. Empty array means no labels.'';\n","version":"202610190002","label":"patient_tags","checksum":"8342fa7cfbfe69adf26deb089c28031e8a688363f54ba47db1c3001948d70c6a","tokens":"ALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fetiquetas\u001fTEXT\u001f[\u001f]\u001fDEFAULT\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fUPDATE\u001fmymind\u001f.\u001fpacientes\u001fSET\u001fetiquetas\u001f=\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fWHERE\u001fetiquetas\u001fIS\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fetiquetas\u001fSET\u001fDEFAULT\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fetiquetas\u001fSET\u001fNOT\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCONSTRAINT\u001fpacientes_etiquetas_limit\u001fCHECK\u001f(\u001fcardinality\u001f(\u001fetiquetas\u001f)\u001f<\u001f=\u001f2\u001f0\u001fAND\u001farray_position\u001f(\u001fetiquetas\u001f,\u001fNULL\u001f)\u001fIS\u001fNULL\u001f)\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fpacientes\u001f.\u001fetiquetas\u001fIS\u001f''Custom patient labels scoped through usuario_id. Empty array means no labels.''","contract":[["column:pacientes.etiquetas","{\"type\": \"text[]\", \"default\": \"ARRAY[]::text[]\", \"required\": true}"],["constraint:pacientes:CHECK (((cardinality(etiquetas) <= 20) AND (array_position(etiquetas, NULL::text) IS NULL)))","present"]]},{"name":"202610190003_clinical_record.sql","sql":"ALTER TABLE mymind.pacientes\n ADD COLUMN IF NOT EXISTS antecedentes TEXT,\n ADD COLUMN IF NOT EXISTS hipotesis_diagnostica TEXT,\n ADD COLUMN IF NOT EXISTS expediente_version INTEGER NOT NULL DEFAULT 0;\n-- Preserve the original notes verbatim. Never overwrite existing structured history.\nUPDATE mymind.pacientes SET antecedentes=notas_confidenciales\n WHERE (antecedentes IS NULL OR antecedentes='''') AND notas_confidenciales IS NOT NULL;\nCREATE FUNCTION mymind.expediente_version_update() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  IF NEW.antecedentes IS NULL THEN NEW.antecedentes:=NEW.notas_confidenciales; END IF;\n ELSIF NEW.motivo_consulta IS DISTINCT FROM OLD.motivo_consulta\n    OR NEW.antecedentes IS DISTINCT FROM OLD.antecedentes\n    OR NEW.hipotesis_diagnostica IS DISTINCT FROM OLD.hipotesis_diagnostica\n    OR NEW.notas_confidenciales IS DISTINCT FROM OLD.notas_confidenciales THEN\n  NEW.expediente_version:=OLD.expediente_version+1;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER expediente_version BEFORE INSERT OR UPDATE ON mymind.pacientes\n FOR EACH ROW EXECUTE FUNCTION mymind.expediente_version_update();\nCOMMENT ON COLUMN mymind.pacientes.antecedentes IS ''Clinical history; legacy notes copied without deleting their original.'';\n","version":"202610190003","label":"clinical_record","checksum":"f08c7566714c6b917998045eee1dc48e1e1f93675db006065d5d312c11e5493b","tokens":"ALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fantecedentes\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fhipotesis_diagnostica\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fexpediente_version\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001fUPDATE\u001fmymind\u001f.\u001fpacientes\u001fSET\u001fantecedentes\u001f=\u001fnotas_confidenciales\u001fWHERE\u001f(\u001fantecedentes\u001fIS\u001fNULL\u001fOR\u001fantecedentes\u001f=\u001f''''\u001f)\u001fAND\u001fnotas_confidenciales\u001fIS\u001fNOT\u001fNULL\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_version_update\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fAS\u001f$$\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  IF NEW.antecedentes IS NULL THEN NEW.antecedentes:=NEW.notas_confidenciales; END IF;\n ELSIF NEW.motivo_consulta IS DISTINCT FROM OLD.motivo_consulta\n    OR NEW.antecedentes IS DISTINCT FROM OLD.antecedentes\n    OR NEW.hipotesis_diagnostica IS DISTINCT FROM OLD.hipotesis_diagnostica\n    OR NEW.notas_confidenciales IS DISTINCT FROM OLD.notas_confidenciales THEN\n  NEW.expediente_version:=OLD.expediente_version+1;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fexpediente_version\u001fBEFORE\u001fINSERT\u001fOR\u001fUPDATE\u001fON\u001fmymind\u001f.\u001fpacientes\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_version_update\u001f(\u001f)\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fpacientes\u001f.\u001fantecedentes\u001fIS\u001f''Clinical history; legacy notes copied without deleting their original.''","contract":[["column:pacientes.antecedentes","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.hipotesis_diagnostica","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:pacientes.expediente_version","{\"type\": \"integer\", \"default\": \"0\", \"required\": true}"],["function:expediente_version_update()","CREATE OR REPLACE FUNCTION mymind.expediente_version_update()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  IF NEW.antecedentes IS NULL THEN NEW.antecedentes:=NEW.notas_confidenciales; END IF;\n ELSIF NEW.motivo_consulta IS DISTINCT FROM OLD.motivo_consulta\n    OR NEW.antecedentes IS DISTINCT FROM OLD.antecedentes\n    OR NEW.hipotesis_diagnostica IS DISTINCT FROM OLD.hipotesis_diagnostica\n    OR NEW.notas_confidenciales IS DISTINCT FROM OLD.notas_confidenciales THEN\n  NEW.expediente_version:=OLD.expediente_version+1;\n END IF;\n RETURN NEW;\nEND $function$\n"],["trigger:pacientes.expediente_version","CREATE TRIGGER expediente_version BEFORE INSERT OR UPDATE ON mymind.pacientes FOR EACH ROW EXECUTE FUNCTION mymind.expediente_version_update()"]]},{"name":"202610260001_clinical_assessments.sql","sql":"CREATE UNIQUE INDEX IF NOT EXISTS pacientes_id_usuario_unique ON mymind.pacientes(id,usuario_id);\nCREATE TABLE mymind.evaluaciones_clinicas (\n id TEXT PRIMARY KEY,\n usuario_id TEXT NOT NULL REFERENCES mymind.usuarios(id) ON DELETE RESTRICT,\n paciente_id TEXT NOT NULL,\n tipo_test TEXT NOT NULL CHECK(tipo_test IN (''PHQ-9'',''GAD-7'',''Personalizado'')),\n nombre_test TEXT,\n modo TEXT NOT NULL CHECK(modo IN (''respuestas'',''puntaje'')),\n puntaje_total INTEGER NOT NULL,\n respuestas JSONB NOT NULL DEFAULT ''[]''::jsonb CHECK(jsonb_typeof(respuestas)=''array''),\n fecha_evaluacion TIMESTAMPTZ NOT NULL,\n creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),\n version_baremo TEXT NOT NULL DEFAULT ''phq-gad-cutoffs-v1'',\n FOREIGN KEY(paciente_id,usuario_id) REFERENCES mymind.pacientes(id,usuario_id) ON DELETE RESTRICT,\n CHECK((tipo_test=''PHQ-9'' AND puntaje_total BETWEEN 0 AND 27) OR (tipo_test=''GAD-7'' AND puntaje_total BETWEEN 0 AND 21) OR (tipo_test=''Personalizado'' AND puntaje_total BETWEEN 0 AND 10000)),\n CHECK((tipo_test=''Personalizado'' AND nombre_test IS NOT NULL AND length(trim(nombre_test)) BETWEEN 1 AND 100 AND modo=''puntaje'') OR (tipo_test<>''Personalizado'' AND nombre_test IS NULL)),\n CHECK((modo=''puntaje'' AND jsonb_array_length(respuestas)=0) OR (modo=''respuestas'' AND jsonb_array_length(respuestas)=CASE WHEN tipo_test=''PHQ-9'' THEN 9 WHEN tipo_test=''GAD-7'' THEN 7 ELSE -1 END))\n);\nALTER TABLE mymind.evaluaciones_clinicas ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON mymind.evaluaciones_clinicas FROM PUBLIC;\nCREATE INDEX evaluaciones_owner_patient_date ON mymind.evaluaciones_clinicas(usuario_id,paciente_id,fecha_evaluacion DESC,id);\n","version":"202610260001","label":"clinical_assessments","checksum":"9dc0997392deb8f5783efbbe916b609a5c3c4381c494789f7c44c67c48ab714d","tokens":"CREATE\u001fUNIQUE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fpacientes_id_usuario_unique\u001fON\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fevaluaciones_clinicas\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001fpaciente_id\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001ftipo_test\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001ftipo_test\u001fIN\u001f(\u001f''PHQ-9''\u001f,\u001f''GAD-7''\u001f,\u001f''Personalizado''\u001f)\u001f)\u001f,\u001fnombre_test\u001fTEXT\u001f,\u001fmodo\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001fmodo\u001fIN\u001f(\u001f''respuestas''\u001f,\u001f''puntaje''\u001f)\u001f)\u001f,\u001fpuntaje_total\u001fINTEGER\u001fNOT\u001fNULL\u001f,\u001frespuestas\u001fJSONB\u001fNOT\u001fNULL\u001fDEFAULT\u001f''[]''\u001f:\u001f:\u001fjsonb\u001fCHECK\u001f(\u001fjsonb_typeof\u001f(\u001frespuestas\u001f)\u001f=\u001f''array''\u001f)\u001f,\u001ffecha_evaluacion\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001fversion_baremo\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''phq-gad-cutoffs-v1''\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fpaciente_id\u001f,\u001fusuario_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001fCHECK\u001f(\u001f(\u001ftipo_test\u001f=\u001f''PHQ-9''\u001fAND\u001fpuntaje_total\u001fBETWEEN\u001f0\u001fAND\u001f2\u001f7\u001f)\u001fOR\u001f(\u001ftipo_test\u001f=\u001f''GAD-7''\u001fAND\u001fpuntaje_total\u001fBETWEEN\u001f0\u001fAND\u001f2\u001f1\u001f)\u001fOR\u001f(\u001ftipo_test\u001f=\u001f''Personalizado''\u001fAND\u001fpuntaje_total\u001fBETWEEN\u001f0\u001fAND\u001f1\u001f0\u001f0\u001f0\u001f0\u001f)\u001f)\u001f,\u001fCHECK\u001f(\u001f(\u001ftipo_test\u001f=\u001f''Personalizado''\u001fAND\u001fnombre_test\u001fIS\u001fNOT\u001fNULL\u001fAND\u001flength\u001f(\u001ftrim\u001f(\u001fnombre_test\u001f)\u001f)\u001fBETWEEN\u001f1\u001fAND\u001f1\u001f0\u001f0\u001fAND\u001fmodo\u001f=\u001f''puntaje''\u001f)\u001fOR\u001f(\u001ftipo_test\u001f<\u001f>\u001f''Personalizado''\u001fAND\u001fnombre_test\u001fIS\u001fNULL\u001f)\u001f)\u001f,\u001fCHECK\u001f(\u001f(\u001fmodo\u001f=\u001f''puntaje''\u001fAND\u001fjsonb_array_length\u001f(\u001frespuestas\u001f)\u001f=\u001f0\u001f)\u001fOR\u001f(\u001fmodo\u001f=\u001f''respuestas''\u001fAND\u001fjsonb_array_length\u001f(\u001frespuestas\u001f)\u001f=\u001fCASE\u001fWHEN\u001ftipo_test\u001f=\u001f''PHQ-9''\u001fTHEN\u001f9\u001fWHEN\u001ftipo_test\u001f=\u001f''GAD-7''\u001fTHEN\u001f7\u001fELSE\u001f-\u001f1\u001fEND\u001f)\u001f)\u001f)\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fevaluaciones_clinicas\u001fENABLE\u001fROW\u001fLEVEL\u001fSECURITY\u001fREVOKE\u001fALL\u001fON\u001fmymind\u001f.\u001fevaluaciones_clinicas\u001fFROM\u001fPUBLIC\u001fCREATE\u001fINDEX\u001fevaluaciones_owner_patient_date\u001fON\u001fmymind\u001f.\u001fevaluaciones_clinicas\u001f(\u001fusuario_id\u001f,\u001fpaciente_id\u001f,\u001ffecha_evaluacion\u001fDESC\u001f,\u001fid\u001f)","contract":[["column:evaluaciones_clinicas.id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.paciente_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.tipo_test","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.nombre_test","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:evaluaciones_clinicas.modo","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.puntaje_total","{\"type\": \"integer\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.respuestas","{\"type\": \"jsonb\", \"default\": \"''[]''::jsonb\", \"required\": true}"],["column:evaluaciones_clinicas.fecha_evaluacion","{\"type\": \"timestamp with time zone\", \"default\": null, \"required\": true}"],["column:evaluaciones_clinicas.creado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:evaluaciones_clinicas.version_baremo","{\"type\": \"text\", \"default\": \"''phq-gad-cutoffs-v1''::text\", \"required\": true}"],["constraint:evaluaciones_clinicas:CHECK ((tipo_test = ANY (ARRAY[''PHQ-9''::text, ''GAD-7''::text, ''Personalizado''::text])))","present"],["constraint:evaluaciones_clinicas:CHECK ((modo = ANY (ARRAY[''respuestas''::text, ''puntaje''::text])))","present"],["constraint:evaluaciones_clinicas:CHECK ((jsonb_typeof(respuestas) = ''array''::text))","present"],["constraint:evaluaciones_clinicas:CHECK ((((tipo_test = ''PHQ-9''::text) AND ((puntaje_total >= 0) AND (puntaje_total <= 27))) OR ((tipo_test = ''GAD-7''::text) AND ((puntaje_total >= 0) AND (puntaje_total <= 21))) OR ((tipo_test = ''Personalizado''::text) AND ((puntaje_total >= 0) AND (puntaje_total <= 10000)))))","present"],["constraint:evaluaciones_clinicas:CHECK ((((tipo_test = ''Personalizado''::text) AND (nombre_test IS NOT NULL) AND ((length(TRIM(BOTH FROM nombre_test)) >= 1) AND (length(TRIM(BOTH FROM nombre_test)) <= 100)) AND (modo = ''puntaje''::text)) OR ((tipo_test <> ''Personalizado''::text) AND (nombre_test IS NULL))))","present"],["constraint:evaluaciones_clinicas:CHECK ((((modo = ''puntaje''::text) AND (jsonb_array_length(respuestas) = 0)) OR ((modo = ''respuestas''::text) AND (jsonb_array_length(respuestas) =\nCASE\n    WHEN (tipo_test = ''PHQ-9''::text) THEN 9\n    WHEN (tipo_test = ''GAD-7''::text) THEN 7\n    ELSE ''-1''::integer\nEND))))","present"],["constraint:evaluaciones_clinicas:PRIMARY KEY (id)","present"],["constraint:evaluaciones_clinicas:FOREIGN KEY (usuario_id) REFERENCES mymind.usuarios(id) ON DELETE RESTRICT","present"],["constraint:evaluaciones_clinicas:FOREIGN KEY (paciente_id, usuario_id) REFERENCES mymind.pacientes(id, usuario_id) ON DELETE RESTRICT","present"],["table:evaluaciones_clinicas","{\"rls\": true, \"force\": false}"],["index:evaluaciones_owner_patient_date","CREATE INDEX evaluaciones_owner_patient_date ON mymind.evaluaciones_clinicas USING btree (usuario_id, paciente_id, fecha_evaluacion DESC, id)"]]},{"name":"202610270001_reconcile_schema.sql","sql":"-- Complete recorded-but-missing schema objects. Preserve existing clinical text and scores.\n-- The legacy archive column was manually created as varchar in production.\n-- Normalize its representation without changing active/archived values.\nALTER TABLE mymind.pacientes ALTER COLUMN status TYPE text USING status::text;\nALTER TABLE mymind.pacientes ALTER COLUMN status SET DEFAULT ''active'';\nALTER TABLE mymind.pacientes DROP CONSTRAINT IF EXISTS pacientes_status_valid;\nALTER TABLE mymind.pacientes ADD CONSTRAINT pacientes_status_valid CHECK(status IN (''active'',''archived''));\nALTER TABLE mymind.usuarios\n ADD COLUMN IF NOT EXISTS google_calendar_token TEXT,\n ADD COLUMN IF NOT EXISTS sync_enabled BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN IF NOT EXISTS recordatorios_email BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN IF NOT EXISTS recordatorios_whatsapp BOOLEAN NOT NULL DEFAULT false,\n ADD COLUMN IF NOT EXISTS recordatorio_horas INTEGER NOT NULL DEFAULT 24 CHECK (recordatorio_horas BETWEEN 1 AND 168);\nCOMMENT ON COLUMN mymind.usuarios.google_calendar_token IS ''Reserved for encrypted OAuth credentials. Never expose through profile APIs.'';\nALTER TABLE mymind.sesiones ADD COLUMN IF NOT EXISTS estado_confirmacion TEXT NOT NULL DEFAULT ''pendiente''\n CHECK (estado_confirmacion IN (''pendiente'',''confirmada'',''recordatorio_enviado'',''cancelada''));\nUPDATE mymind.sesiones SET estado_confirmacion=''cancelada'' WHERE estado_sesion=''Cancelada'';\nUPDATE mymind.sesiones SET estado_confirmacion=''pendiente'' WHERE estado_confirmacion IS NULL;\nALTER TABLE mymind.sesiones ALTER COLUMN estado_confirmacion SET NOT NULL;\nDO $state$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=''mymind.sesiones''::regclass AND conname=''sesiones_estado_confirmacion_check'') THEN ALTER TABLE mymind.sesiones ADD CONSTRAINT sesiones_estado_confirmacion_check CHECK(estado_confirmacion IN (''pendiente'',''confirmada'',''recordatorio_enviado'',''cancelada'')); END IF; END $state$;\nCREATE TABLE IF NOT EXISTS mymind.agenda_emails (\n id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,\n sesion_id TEXT NOT NULL REFERENCES mymind.sesiones(id) ON DELETE CASCADE,\n usuario_id TEXT NOT NULL REFERENCES mymind.usuarios(id) ON DELETE CASCADE,\n fecha_cita TIMESTAMPTZ NOT NULL,\n tipo TEXT NOT NULL CHECK(tipo IN (''confirmacion'',''recordatorio'')),\n destinatario TEXT NOT NULL, modalidad TEXT NOT NULL, zona_horaria TEXT NOT NULL,\n enviar_en TIMESTAMPTZ NOT NULL, creado_en TIMESTAMPTZ NOT NULL DEFAULT now(),\n estado TEXT NOT NULL DEFAULT ''pendiente'' CHECK(estado IN (''pendiente'',''enviado'',''omitido'',''fallido'')),\n intentos INTEGER NOT NULL DEFAULT 0, enviado_en TIMESTAMPTZ,\n UNIQUE(sesion_id,fecha_cita,tipo)\n);\nALTER TABLE mymind.agenda_emails ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON mymind.agenda_emails FROM PUBLIC;\nCREATE INDEX IF NOT EXISTS agenda_emails_pending ON mymind.agenda_emails(enviar_en) WHERE estado=''pendiente'';\nCREATE OR REPLACE FUNCTION mymind.agenda_state() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF NEW.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''cancelada'';\n ELSIF TG_OP=''UPDATE'' THEN\n  IF NEW.fecha_hora IS DISTINCT FROM OLD.fecha_hora OR OLD.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''pendiente''; END IF;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE TRIGGER agenda_state BEFORE INSERT OR UPDATE OF fecha_hora,estado_sesion ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_state();\nCREATE OR REPLACE FUNCTION mymind.agenda_queue_email() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nDECLARE recipient TEXT; owner_id TEXT; enabled BOOLEAN; hours_before INTEGER; zone TEXT;\nBEGIN\n IF NEW.estado_sesion<>''Programada'' OR NEW.fecha_hora<=now() THEN RETURN NEW; END IF;\n SELECT p.email,p.usuario_id,u.recordatorios_email,u.recordatorio_horas,COALESCE(c.zona_horaria,''America/Santiago'')\n INTO recipient,owner_id,enabled,hours_before,zone FROM pacientes p JOIN usuarios u ON u.id=p.usuario_id\n LEFT JOIN configuracion_sitio c ON c.profesional_id=u.id WHERE p.id=NEW.paciente_id;\n IF enabled AND recipient IS NOT NULL AND recipient<>'''' THEN\n INSERT INTO agenda_emails(sesion_id,usuario_id,fecha_cita,tipo,destinatario,modalidad,zona_horaria,enviar_en)\n VALUES (NEW.id,owner_id,NEW.fecha_hora,''confirmacion'',recipient,NEW.modalidad,zone,now()),\n (NEW.id,owner_id,NEW.fecha_hora,''recordatorio'',recipient,NEW.modalidad,zone,GREATEST(now()+interval ''5 minutes'',NEW.fecha_hora-hours_before*interval ''1 hour''))\n ON CONFLICT DO NOTHING;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE TRIGGER agenda_email AFTER INSERT OR UPDATE OF fecha_hora,estado_sesion,modalidad ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.agenda_queue_email();\n\nALTER TABLE mymind.pacientes ADD COLUMN IF NOT EXISTS etiquetas TEXT[] DEFAULT ARRAY[]::TEXT[];\nUPDATE mymind.pacientes SET etiquetas=ARRAY[]::TEXT[] WHERE etiquetas IS NULL;\nALTER TABLE mymind.pacientes ALTER COLUMN etiquetas SET DEFAULT ARRAY[]::TEXT[];\nALTER TABLE mymind.pacientes ALTER COLUMN etiquetas SET NOT NULL;\nDO $tags$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=''mymind.pacientes''::regclass AND conname=''pacientes_etiquetas_limit'') THEN ALTER TABLE mymind.pacientes ADD CONSTRAINT pacientes_etiquetas_limit CHECK (cardinality(etiquetas)<=20 AND array_position(etiquetas,NULL) IS NULL); END IF; END $tags$;\nCOMMENT ON COLUMN mymind.pacientes.etiquetas IS ''Custom patient labels scoped through usuario_id. Empty array means no labels.'';\n\nALTER TABLE mymind.pacientes\n ADD COLUMN IF NOT EXISTS antecedentes TEXT,\n ADD COLUMN IF NOT EXISTS hipotesis_diagnostica TEXT,\n ADD COLUMN IF NOT EXISTS expediente_version INTEGER NOT NULL DEFAULT 0;\n-- Existing clinical text is retained verbatim; no legacy text is overwritten.\nALTER TABLE mymind.pacientes ALTER COLUMN antecedentes DROP DEFAULT, ALTER COLUMN hipotesis_diagnostica DROP DEFAULT;\nCREATE OR REPLACE FUNCTION mymind.expediente_version_update() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  IF NEW.antecedentes IS NULL THEN NEW.antecedentes:=NEW.notas_confidenciales; END IF;\n ELSIF NEW.motivo_consulta IS DISTINCT FROM OLD.motivo_consulta\n    OR NEW.antecedentes IS DISTINCT FROM OLD.antecedentes\n    OR NEW.hipotesis_diagnostica IS DISTINCT FROM OLD.hipotesis_diagnostica\n    OR NEW.notas_confidenciales IS DISTINCT FROM OLD.notas_confidenciales THEN\n  NEW.expediente_version:=OLD.expediente_version+1;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE OR REPLACE TRIGGER expediente_version BEFORE INSERT OR UPDATE ON mymind.pacientes\n FOR EACH ROW EXECUTE FUNCTION mymind.expediente_version_update();\nCOMMENT ON COLUMN mymind.pacientes.antecedentes IS ''Clinical history; legacy notes copied without deleting their original.'';\n\nALTER TABLE mymind.evaluaciones_clinicas ALTER COLUMN fecha_evaluacion DROP DEFAULT;\nDO $guard$\nDECLARE missing text; role_name text;\nBEGIN\n SELECT string_agg(expected.name, '', '') INTO missing\n FROM (VALUES (''id'',''text'',true), (''usuario_id'',''text'',true), (''paciente_id'',''text'',true),\n (''tipo_test'',''text'',true), (''nombre_test'',''text'',false), (''modo'',''text'',true),\n (''puntaje_total'',''integer'',true), (''respuestas'',''jsonb'',true),\n (''fecha_evaluacion'',''timestamp with time zone'',true),\n (''creado_en'',''timestamp with time zone'',true), (''version_baremo'',''text'',true)) expected(name,type,required)\n LEFT JOIN pg_attribute a ON a.attrelid=''mymind.evaluaciones_clinicas''::regclass\n   AND a.attname=expected.name AND a.attnum>0 AND NOT a.attisdropped\n WHERE a.attname IS NULL OR format_type(a.atttypid,a.atttypmod)<>expected.type OR a.attnotnull<>expected.required;\n IF missing IS NOT NULL THEN\n   RAISE EXCEPTION ''Assessment schema mismatch: %. Stop and review before recording migration history.'',missing;\n END IF;\n IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''mymind'' AND tablename=''evaluaciones_clinicas'') THEN\n   RAISE EXCEPTION ''Unexpected assessment RLS policy. This application authorizes access in its server API.'';\n END IF;\n ALTER TABLE mymind.evaluaciones_clinicas ENABLE ROW LEVEL SECURITY;\n REVOKE ALL ON mymind.evaluaciones_clinicas FROM PUBLIC;\n FOREACH role_name IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n   IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN\n     EXECUTE format(''REVOKE ALL ON mymind.evaluaciones_clinicas FROM %I'',role_name);\n   END IF;\n END LOOP;\nEND $guard$;\n","version":"202610270001","label":"reconcile_schema","checksum":"f0e10b9d2d4f2ad74dd5185816587ab1a9926cc2d1d847500a0feb4fdc7fccbf","tokens":"ALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fstatus\u001fTYPE\u001ftext\u001fUSING\u001fstatus\u001f:\u001f:\u001ftext\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fstatus\u001fSET\u001fDEFAULT\u001f''active''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fDROP\u001fCONSTRAINT\u001fIF\u001fEXISTS\u001fpacientes_status_valid\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCONSTRAINT\u001fpacientes_status_valid\u001fCHECK\u001f(\u001fstatus\u001fIN\u001f(\u001f''active''\u001f,\u001f''archived''\u001f)\u001f)\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fusuarios\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fgoogle_calendar_token\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fsync_enabled\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001frecordatorios_email\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001frecordatorios_whatsapp\u001fBOOLEAN\u001fNOT\u001fNULL\u001fDEFAULT\u001ffalse\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001frecordatorio_horas\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f2\u001f4\u001fCHECK\u001f(\u001frecordatorio_horas\u001fBETWEEN\u001f1\u001fAND\u001f1\u001f6\u001f8\u001f)\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fusuarios\u001f.\u001fgoogle_calendar_token\u001fIS\u001f''Reserved for encrypted OAuth credentials. Never expose through profile APIs.''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fsesiones\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001festado_confirmacion\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''pendiente''\u001fCHECK\u001f(\u001festado_confirmacion\u001fIN\u001f(\u001f''pendiente''\u001f,\u001f''confirmada''\u001f,\u001f''recordatorio_enviado''\u001f,\u001f''cancelada''\u001f)\u001f)\u001fUPDATE\u001fmymind\u001f.\u001fsesiones\u001fSET\u001festado_confirmacion\u001f=\u001f''cancelada''\u001fWHERE\u001festado_sesion\u001f=\u001f''Cancelada''\u001fUPDATE\u001fmymind\u001f.\u001fsesiones\u001fSET\u001festado_confirmacion\u001f=\u001f''pendiente''\u001fWHERE\u001festado_confirmacion\u001fIS\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fsesiones\u001fALTER\u001fCOLUMN\u001festado_confirmacion\u001fSET\u001fNOT\u001fNULL\u001fDO\u001f$state$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=''mymind.sesiones''::regclass AND conname=''sesiones_estado_confirmacion_check'') THEN ALTER TABLE mymind.sesiones ADD CONSTRAINT sesiones_estado_confirmacion_check CHECK(estado_confirmacion IN (''pendiente'',''confirmada'',''recordatorio_enviado'',''cancelada'')); END IF; END $state$\u001fCREATE\u001fTABLE\u001fIF\u001fNOT\u001fEXISTS\u001fmymind\u001f.\u001fagenda_emails\u001f(\u001fid\u001fTEXT\u001fPRIMARY\u001fKEY\u001fDEFAULT\u001fgen_random_uuid\u001f(\u001f)\u001f:\u001f:\u001ftext\u001f,\u001fsesion_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fsesiones\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001fusuario_id\u001fTEXT\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fCASCADE\u001f,\u001ffecha_cita\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001ftipo\u001fTEXT\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001ftipo\u001fIN\u001f(\u001f''confirmacion''\u001f,\u001f''recordatorio''\u001f)\u001f)\u001f,\u001fdestinatario\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fmodalidad\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fzona_horaria\u001fTEXT\u001fNOT\u001fNULL\u001f,\u001fenviar_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001f,\u001fcreado_en\u001fTIMESTAMPTZ\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001festado\u001fTEXT\u001fNOT\u001fNULL\u001fDEFAULT\u001f''pendiente''\u001fCHECK\u001f(\u001festado\u001fIN\u001f(\u001f''pendiente''\u001f,\u001f''enviado''\u001f,\u001f''omitido''\u001f,\u001f''fallido''\u001f)\u001f)\u001f,\u001fintentos\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001f,\u001fenviado_en\u001fTIMESTAMPTZ\u001f,\u001fUNIQUE\u001f(\u001fsesion_id\u001f,\u001ffecha_cita\u001f,\u001ftipo\u001f)\u001f)\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fagenda_emails\u001fENABLE\u001fROW\u001fLEVEL\u001fSECURITY\u001fREVOKE\u001fALL\u001fON\u001fmymind\u001f.\u001fagenda_emails\u001fFROM\u001fPUBLIC\u001fCREATE\u001fINDEX\u001fIF\u001fNOT\u001fEXISTS\u001fagenda_emails_pending\u001fON\u001fmymind\u001f.\u001fagenda_emails\u001f(\u001fenviar_en\u001f)\u001fWHERE\u001festado\u001f=\u001f''pendiente''\u001fCREATE\u001fOR\u001fREPLACE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_state\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF NEW.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''cancelada'';\n ELSIF TG_OP=''UPDATE'' THEN\n  IF NEW.fecha_hora IS DISTINCT FROM OLD.fecha_hora OR OLD.estado_sesion=''Cancelada'' THEN NEW.estado_confirmacion:=''pendiente''; END IF;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fOR\u001fREPLACE\u001fTRIGGER\u001fagenda_state\u001fBEFORE\u001fINSERT\u001fOR\u001fUPDATE\u001fOF\u001ffecha_hora\u001f,\u001festado_sesion\u001fON\u001fmymind\u001f.\u001fsesiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_state\u001f(\u001f)\u001fCREATE\u001fOR\u001fREPLACE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_queue_email\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nDECLARE recipient TEXT; owner_id TEXT; enabled BOOLEAN; hours_before INTEGER; zone TEXT;\nBEGIN\n IF NEW.estado_sesion<>''Programada'' OR NEW.fecha_hora<=now() THEN RETURN NEW; END IF;\n SELECT p.email,p.usuario_id,u.recordatorios_email,u.recordatorio_horas,COALESCE(c.zona_horaria,''America/Santiago'')\n INTO recipient,owner_id,enabled,hours_before,zone FROM pacientes p JOIN usuarios u ON u.id=p.usuario_id\n LEFT JOIN configuracion_sitio c ON c.profesional_id=u.id WHERE p.id=NEW.paciente_id;\n IF enabled AND recipient IS NOT NULL AND recipient<>'''' THEN\n INSERT INTO agenda_emails(sesion_id,usuario_id,fecha_cita,tipo,destinatario,modalidad,zona_horaria,enviar_en)\n VALUES (NEW.id,owner_id,NEW.fecha_hora,''confirmacion'',recipient,NEW.modalidad,zone,now()),\n (NEW.id,owner_id,NEW.fecha_hora,''recordatorio'',recipient,NEW.modalidad,zone,GREATEST(now()+interval ''5 minutes'',NEW.fecha_hora-hours_before*interval ''1 hour''))\n ON CONFLICT DO NOTHING;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fOR\u001fREPLACE\u001fTRIGGER\u001fagenda_email\u001fAFTER\u001fINSERT\u001fOR\u001fUPDATE\u001fOF\u001ffecha_hora\u001f,\u001festado_sesion\u001f,\u001fmodalidad\u001fON\u001fmymind\u001f.\u001fsesiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fagenda_queue_email\u001f(\u001f)\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fetiquetas\u001fTEXT\u001f[\u001f]\u001fDEFAULT\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fUPDATE\u001fmymind\u001f.\u001fpacientes\u001fSET\u001fetiquetas\u001f=\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fWHERE\u001fetiquetas\u001fIS\u001fNULL\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fetiquetas\u001fSET\u001fDEFAULT\u001fARRAY\u001f[\u001f]\u001f:\u001f:\u001fTEXT\u001f[\u001f]\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fetiquetas\u001fSET\u001fNOT\u001fNULL\u001fDO\u001f$tags$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=''mymind.pacientes''::regclass AND conname=''pacientes_etiquetas_limit'') THEN ALTER TABLE mymind.pacientes ADD CONSTRAINT pacientes_etiquetas_limit CHECK (cardinality(etiquetas)<=20 AND array_position(etiquetas,NULL) IS NULL); END IF; END $tags$\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fpacientes\u001f.\u001fetiquetas\u001fIS\u001f''Custom patient labels scoped through usuario_id. Empty array means no labels.''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fantecedentes\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fhipotesis_diagnostica\u001fTEXT\u001f,\u001fADD\u001fCOLUMN\u001fIF\u001fNOT\u001fEXISTS\u001fexpediente_version\u001fINTEGER\u001fNOT\u001fNULL\u001fDEFAULT\u001f0\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fpacientes\u001fALTER\u001fCOLUMN\u001fantecedentes\u001fDROP\u001fDEFAULT\u001f,\u001fALTER\u001fCOLUMN\u001fhipotesis_diagnostica\u001fDROP\u001fDEFAULT\u001fCREATE\u001fOR\u001fREPLACE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_version_update\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fAS\u001f$$\nBEGIN\n IF TG_OP=''INSERT'' THEN\n  IF NEW.antecedentes IS NULL THEN NEW.antecedentes:=NEW.notas_confidenciales; END IF;\n ELSIF NEW.motivo_consulta IS DISTINCT FROM OLD.motivo_consulta\n    OR NEW.antecedentes IS DISTINCT FROM OLD.antecedentes\n    OR NEW.hipotesis_diagnostica IS DISTINCT FROM OLD.hipotesis_diagnostica\n    OR NEW.notas_confidenciales IS DISTINCT FROM OLD.notas_confidenciales THEN\n  NEW.expediente_version:=OLD.expediente_version+1;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fOR\u001fREPLACE\u001fTRIGGER\u001fexpediente_version\u001fBEFORE\u001fINSERT\u001fOR\u001fUPDATE\u001fON\u001fmymind\u001f.\u001fpacientes\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_version_update\u001f(\u001f)\u001fCOMMENT\u001fON\u001fCOLUMN\u001fmymind\u001f.\u001fpacientes\u001f.\u001fantecedentes\u001fIS\u001f''Clinical history; legacy notes copied without deleting their original.''\u001fALTER\u001fTABLE\u001fmymind\u001f.\u001fevaluaciones_clinicas\u001fALTER\u001fCOLUMN\u001ffecha_evaluacion\u001fDROP\u001fDEFAULT\u001fDO\u001f$guard$\nDECLARE missing text; role_name text;\nBEGIN\n SELECT string_agg(expected.name, '', '') INTO missing\n FROM (VALUES (''id'',''text'',true), (''usuario_id'',''text'',true), (''paciente_id'',''text'',true),\n (''tipo_test'',''text'',true), (''nombre_test'',''text'',false), (''modo'',''text'',true),\n (''puntaje_total'',''integer'',true), (''respuestas'',''jsonb'',true),\n (''fecha_evaluacion'',''timestamp with time zone'',true),\n (''creado_en'',''timestamp with time zone'',true), (''version_baremo'',''text'',true)) expected(name,type,required)\n LEFT JOIN pg_attribute a ON a.attrelid=''mymind.evaluaciones_clinicas''::regclass\n   AND a.attname=expected.name AND a.attnum>0 AND NOT a.attisdropped\n WHERE a.attname IS NULL OR format_type(a.atttypid,a.atttypmod)<>expected.type OR a.attnotnull<>expected.required;\n IF missing IS NOT NULL THEN\n   RAISE EXCEPTION ''Assessment schema mismatch: %. Stop and review before recording migration history.'',missing;\n END IF;\n IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname=''mymind'' AND tablename=''evaluaciones_clinicas'') THEN\n   RAISE EXCEPTION ''Unexpected assessment RLS policy. This application authorizes access in its server API.'';\n END IF;\n ALTER TABLE mymind.evaluaciones_clinicas ENABLE ROW LEVEL SECURITY;\n REVOKE ALL ON mymind.evaluaciones_clinicas FROM PUBLIC;\n FOREACH role_name IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n   IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN\n     EXECUTE format(''REVOKE ALL ON mymind.evaluaciones_clinicas FROM %I'',role_name);\n   END IF;\n END LOOP;\nEND $guard$","contract":[]},{"name":"202610280001_clinical_care.sql","sql":"-- Structured clinical care. Legacy patient fields and evolution notes are retained verbatim.\nCREATE TABLE mymind.fichas_atencion (\n paciente_id text PRIMARY KEY, usuario_id text NOT NULL,\n datos jsonb NOT NULL DEFAULT ''{}''::jsonb CHECK(jsonb_typeof(datos)=''object''),\n version integer NOT NULL DEFAULT 1 CHECK(version>0),\n actualizado_por text NOT NULL REFERENCES mymind.usuarios(id), actualizado_en timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(paciente_id,usuario_id) REFERENCES mymind.pacientes(id,usuario_id) ON DELETE RESTRICT\n);\nCREATE TABLE mymind.objetivos_terapeuticos (\n id text PRIMARY KEY, paciente_id text NOT NULL, usuario_id text NOT NULL,\n titulo text NOT NULL CHECK(length(trim(titulo)) BETWEEN 1 AND 300), descripcion text, criterio_logro text,\n estado text NOT NULL DEFAULT ''activo'' CHECK(estado IN (''activo'',''logrado'',''pausado'')),\n fecha_revision date, version integer NOT NULL DEFAULT 1 CHECK(version>0),\n creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now(),\n actualizado_por text NOT NULL REFERENCES mymind.usuarios(id),\n FOREIGN KEY(paciente_id,usuario_id) REFERENCES mymind.pacientes(id,usuario_id) ON DELETE RESTRICT\n);\nCREATE UNIQUE INDEX sesiones_id_paciente_unique ON mymind.sesiones(id,paciente_id);\nCREATE TABLE mymind.notas_clinicas (\n id text PRIMARY KEY, paciente_id text NOT NULL, usuario_id text NOT NULL, sesion_id text NOT NULL UNIQUE,\n contenido jsonb NOT NULL CHECK(jsonb_typeof(contenido)=''object''),\n estado text NOT NULL DEFAULT ''borrador'' CHECK(estado IN (''borrador'',''finalizada'')),\n version integer NOT NULL DEFAULT 1 CHECK(version>0),\n creado_en timestamptz NOT NULL DEFAULT now(), actualizado_en timestamptz NOT NULL DEFAULT now(),\n creado_por text NOT NULL REFERENCES mymind.usuarios(id), actualizado_por text NOT NULL REFERENCES mymind.usuarios(id),\n finalizada_en timestamptz, finalizada_por text REFERENCES mymind.usuarios(id),\n CHECK((estado=''borrador'' AND finalizada_en IS NULL AND finalizada_por IS NULL) OR (estado=''finalizada'' AND finalizada_en IS NOT NULL AND finalizada_por IS NOT NULL)),\n FOREIGN KEY(paciente_id,usuario_id) REFERENCES mymind.pacientes(id,usuario_id) ON DELETE RESTRICT,\n FOREIGN KEY(sesion_id,paciente_id) REFERENCES mymind.sesiones(id,paciente_id) ON DELETE RESTRICT\n);\nCREATE TABLE mymind.nota_revisiones (\n nota_id text NOT NULL REFERENCES mymind.notas_clinicas(id) ON DELETE RESTRICT, version integer NOT NULL,\n contenido jsonb NOT NULL, estado text NOT NULL, autor_id text NOT NULL REFERENCES mymind.usuarios(id),\n registrado_en timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(nota_id,version)\n);\nCREATE TABLE mymind.nota_adendas (\n id text PRIMARY KEY, nota_id text NOT NULL REFERENCES mymind.notas_clinicas(id) ON DELETE RESTRICT,\n texto text NOT NULL CHECK(length(trim(texto)) BETWEEN 1 AND 10000),\n autor_id text NOT NULL REFERENCES mymind.usuarios(id), registrado_en timestamptz NOT NULL DEFAULT now()\n);\nCREATE TABLE mymind.atencion_eventos (\n id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n paciente_id text NOT NULL, usuario_id text NOT NULL, actor_id text NOT NULL REFERENCES mymind.usuarios(id),\n accion text NOT NULL, recurso_id text, version integer, registrado_en timestamptz NOT NULL DEFAULT now(),\n FOREIGN KEY(paciente_id,usuario_id) REFERENCES mymind.pacientes(id,usuario_id) ON DELETE RESTRICT\n);\nCREATE INDEX objetivos_patient ON mymind.objetivos_terapeuticos(usuario_id,paciente_id,creado_en);\nCREATE INDEX notas_patient ON mymind.notas_clinicas(usuario_id,paciente_id,creado_en DESC);\nCREATE INDEX eventos_patient ON mymind.atencion_eventos(usuario_id,paciente_id,id DESC);\nCREATE FUNCTION mymind.nota_ciclo_vida() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''Clinical notes cannot be deleted'' USING ERRCODE=''23514''; END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF OLD.estado=''finalizada'' THEN RAISE EXCEPTION ''Finalized note is immutable; append an addendum'' USING ERRCODE=''23514''; END IF;\n  IF (NEW.id,NEW.paciente_id,NEW.usuario_id,NEW.sesion_id,NEW.creado_en,NEW.creado_por) IS DISTINCT FROM (OLD.id,OLD.paciente_id,OLD.usuario_id,OLD.sesion_id,OLD.creado_en,OLD.creado_por) THEN RAISE EXCEPTION ''Note identity is immutable'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=OLD.version+1;\n ELSE\n  IF NEW.estado<>''borrador'' THEN RAISE EXCEPTION ''Create a draft first'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=1; NEW.creado_en:=now();\n END IF;\n NEW.actualizado_en:=now();\n IF NEW.actualizado_por<>NEW.usuario_id OR NEW.creado_por<>NEW.usuario_id THEN RAISE EXCEPTION ''Note author must own the patient'' USING ERRCODE=''23514''; END IF;\n IF NEW.estado=''finalizada'' THEN\n  PERFORM 1 FROM sesiones WHERE id=NEW.sesion_id AND paciente_id=NEW.paciente_id AND estado_sesion=''Realizada'' AND fecha_hora::timestamptz<=now() FOR UPDATE;\n  IF NOT FOUND OR coalesce(trim(NEW.contenido->>''resumen''),'''')='''' THEN RAISE EXCEPTION ''Finalization requires a completed session and summary'' USING ERRCODE=''23514''; END IF;\n  NEW.finalizada_en:=now(); NEW.finalizada_por:=NEW.actualizado_por;\n END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER nota_ciclo_vida BEFORE INSERT OR UPDATE OR DELETE ON mymind.notas_clinicas FOR EACH ROW EXECUTE FUNCTION mymind.nota_ciclo_vida();\nCREATE FUNCTION mymind.nota_guardar_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n INSERT INTO nota_revisiones(nota_id,version,contenido,estado,autor_id) VALUES(NEW.id,NEW.version,NEW.contenido,NEW.estado,NEW.actualizado_por);\n RETURN NEW;\nEND $$;\nCREATE TRIGGER nota_revision AFTER INSERT OR UPDATE ON mymind.notas_clinicas FOR EACH ROW EXECUTE FUNCTION mymind.nota_guardar_revision();\nCREATE FUNCTION mymind.historial_inmutable() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN RAISE EXCEPTION ''Append-only clinical history'' USING ERRCODE=''23514''; END $$;\nCREATE TRIGGER revisiones_inmutables BEFORE UPDATE OR DELETE ON mymind.nota_revisiones FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable();\nCREATE TRIGGER adendas_inmutables BEFORE UPDATE OR DELETE ON mymind.nota_adendas FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable();\nCREATE TRIGGER eventos_inmutables BEFORE UPDATE OR DELETE ON mymind.atencion_eventos FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable();\nCREATE FUNCTION mymind.validar_adenda() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM notas_clinicas WHERE id=NEW.nota_id AND estado=''finalizada'' AND usuario_id=NEW.autor_id) THEN RAISE EXCEPTION ''Addendum requires a finalized note owned by its author'' USING ERRCODE=''23514''; END IF;\n NEW.registrado_en:=now(); RETURN NEW;\nEND $$;\nCREATE TRIGGER adenda_validar BEFORE INSERT ON mymind.nota_adendas FOR EACH ROW EXECUTE FUNCTION mymind.validar_adenda();\nDO $$ DECLARE t text; r text; BEGIN\n FOREACH t IN ARRAY ARRAY[''fichas_atencion'',''objetivos_terapeuticos'',''notas_clinicas'',''nota_revisiones'',''nota_adendas'',''atencion_eventos''] LOOP\n  EXECUTE format(''ALTER TABLE mymind.%I ENABLE ROW LEVEL SECURITY'',t);\n  EXECUTE format(''REVOKE ALL ON mymind.%I FROM PUBLIC'',t);\n  FOREACH r IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n   IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format(''REVOKE ALL ON mymind.%I FROM %I'',t,r); END IF;\n  END LOOP;\n END LOOP;\nEND $$;\nCREATE FUNCTION mymind.sesion_finalizada_inmutable() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF (NEW.paciente_id,NEW.fecha_hora,NEW.duracion_minutos,NEW.modalidad,NEW.estado_sesion) IS DISTINCT FROM (OLD.paciente_id,OLD.fecha_hora,OLD.duracion_minutos,OLD.modalidad,OLD.estado_sesion) AND EXISTS(SELECT 1 FROM notas_clinicas WHERE sesion_id=OLD.id AND estado=''finalizada'') THEN RAISE EXCEPTION ''Session has a finalized clinical note'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER sesion_finalizada_inmutable BEFORE UPDATE ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.sesion_finalizada_inmutable();\nCREATE FUNCTION mymind.expediente_trazabilidad() RETURNS trigger LANGUAGE plpgsql SET search_path=mymind,pg_temp AS $$\nBEGIN\n IF (NEW.motivo_consulta,NEW.antecedentes,NEW.hipotesis_diagnostica,NEW.notas_confidenciales) IS DISTINCT FROM (OLD.motivo_consulta,OLD.antecedentes,OLD.hipotesis_diagnostica,OLD.notas_confidenciales) THEN\n INSERT INTO atencion_eventos(paciente_id,usuario_id,actor_id,accion,recurso_id,version) VALUES(NEW.id,NEW.usuario_id,NEW.usuario_id,''expediente_actualizado'',NEW.id,NEW.expediente_version);\n END IF; RETURN NEW;\nEND $$;\nCREATE TRIGGER expediente_trazabilidad AFTER UPDATE ON mymind.pacientes FOR EACH ROW EXECUTE FUNCTION mymind.expediente_trazabilidad();\n","version":"202610280001","label":"clinical_care","checksum":"16f52fc7771bfbb0d5ee3fdac3b8a9f54e5f30a83ee699f1e404c5402615bdb9","tokens":"CREATE\u001fTABLE\u001fmymind\u001f.\u001ffichas_atencion\u001f(\u001fpaciente_id\u001ftext\u001fPRIMARY\u001fKEY\u001f,\u001fusuario_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001fdatos\u001fjsonb\u001fNOT\u001fNULL\u001fDEFAULT\u001f''{}''\u001f:\u001f:\u001fjsonb\u001fCHECK\u001f(\u001fjsonb_typeof\u001f(\u001fdatos\u001f)\u001f=\u001f''object''\u001f)\u001f,\u001fversion\u001finteger\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001fCHECK\u001f(\u001fversion\u001f>\u001f0\u001f)\u001f,\u001factualizado_por\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001factualizado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fpaciente_id\u001f,\u001fusuario_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fobjetivos_terapeuticos\u001f(\u001fid\u001ftext\u001fPRIMARY\u001fKEY\u001f,\u001fpaciente_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001ftitulo\u001ftext\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001flength\u001f(\u001ftrim\u001f(\u001ftitulo\u001f)\u001f)\u001fBETWEEN\u001f1\u001fAND\u001f3\u001f0\u001f0\u001f)\u001f,\u001fdescripcion\u001ftext\u001f,\u001fcriterio_logro\u001ftext\u001f,\u001festado\u001ftext\u001fNOT\u001fNULL\u001fDEFAULT\u001f''activo''\u001fCHECK\u001f(\u001festado\u001fIN\u001f(\u001f''activo''\u001f,\u001f''logrado''\u001f,\u001f''pausado''\u001f)\u001f)\u001f,\u001ffecha_revision\u001fdate\u001f,\u001fversion\u001finteger\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001fCHECK\u001f(\u001fversion\u001f>\u001f0\u001f)\u001f,\u001fcreado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001factualizado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001factualizado_por\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fpaciente_id\u001f,\u001fusuario_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f)\u001fCREATE\u001fUNIQUE\u001fINDEX\u001fsesiones_id_paciente_unique\u001fON\u001fmymind\u001f.\u001fsesiones\u001f(\u001fid\u001f,\u001fpaciente_id\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fnotas_clinicas\u001f(\u001fid\u001ftext\u001fPRIMARY\u001fKEY\u001f,\u001fpaciente_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001fsesion_id\u001ftext\u001fNOT\u001fNULL\u001fUNIQUE\u001f,\u001fcontenido\u001fjsonb\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001fjsonb_typeof\u001f(\u001fcontenido\u001f)\u001f=\u001f''object''\u001f)\u001f,\u001festado\u001ftext\u001fNOT\u001fNULL\u001fDEFAULT\u001f''borrador''\u001fCHECK\u001f(\u001festado\u001fIN\u001f(\u001f''borrador''\u001f,\u001f''finalizada''\u001f)\u001f)\u001f,\u001fversion\u001finteger\u001fNOT\u001fNULL\u001fDEFAULT\u001f1\u001fCHECK\u001f(\u001fversion\u001f>\u001f0\u001f)\u001f,\u001fcreado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001factualizado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001fcreado_por\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001factualizado_por\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001ffinalizada_en\u001ftimestamptz\u001f,\u001ffinalizada_por\u001ftext\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fCHECK\u001f(\u001f(\u001festado\u001f=\u001f''borrador''\u001fAND\u001ffinalizada_en\u001fIS\u001fNULL\u001fAND\u001ffinalizada_por\u001fIS\u001fNULL\u001f)\u001fOR\u001f(\u001festado\u001f=\u001f''finalizada''\u001fAND\u001ffinalizada_en\u001fIS\u001fNOT\u001fNULL\u001fAND\u001ffinalizada_por\u001fIS\u001fNOT\u001fNULL\u001f)\u001f)\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fpaciente_id\u001f,\u001fusuario_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fsesion_id\u001f,\u001fpaciente_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fsesiones\u001f(\u001fid\u001f,\u001fpaciente_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fnota_revisiones\u001f(\u001fnota_id\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fnotas_clinicas\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001fversion\u001finteger\u001fNOT\u001fNULL\u001f,\u001fcontenido\u001fjsonb\u001fNOT\u001fNULL\u001f,\u001festado\u001ftext\u001fNOT\u001fNULL\u001f,\u001fautor_id\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fregistrado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001fPRIMARY\u001fKEY\u001f(\u001fnota_id\u001f,\u001fversion\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fnota_adendas\u001f(\u001fid\u001ftext\u001fPRIMARY\u001fKEY\u001f,\u001fnota_id\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fnotas_clinicas\u001f(\u001fid\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f,\u001ftexto\u001ftext\u001fNOT\u001fNULL\u001fCHECK\u001f(\u001flength\u001f(\u001ftrim\u001f(\u001ftexto\u001f)\u001f)\u001fBETWEEN\u001f1\u001fAND\u001f1\u001f0\u001f0\u001f0\u001f0\u001f)\u001f,\u001fautor_id\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001fregistrado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f)\u001fCREATE\u001fTABLE\u001fmymind\u001f.\u001fatencion_eventos\u001f(\u001fid\u001fbigint\u001fGENERATED\u001fALWAYS\u001fAS\u001fIDENTITY\u001fPRIMARY\u001fKEY\u001f,\u001fpaciente_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001fusuario_id\u001ftext\u001fNOT\u001fNULL\u001f,\u001factor_id\u001ftext\u001fNOT\u001fNULL\u001fREFERENCES\u001fmymind\u001f.\u001fusuarios\u001f(\u001fid\u001f)\u001f,\u001faccion\u001ftext\u001fNOT\u001fNULL\u001f,\u001frecurso_id\u001ftext\u001f,\u001fversion\u001finteger\u001f,\u001fregistrado_en\u001ftimestamptz\u001fNOT\u001fNULL\u001fDEFAULT\u001fnow\u001f(\u001f)\u001f,\u001fFOREIGN\u001fKEY\u001f(\u001fpaciente_id\u001f,\u001fusuario_id\u001f)\u001fREFERENCES\u001fmymind\u001f.\u001fpacientes\u001f(\u001fid\u001f,\u001fusuario_id\u001f)\u001fON\u001fDELETE\u001fRESTRICT\u001f)\u001fCREATE\u001fINDEX\u001fobjetivos_patient\u001fON\u001fmymind\u001f.\u001fobjetivos_terapeuticos\u001f(\u001fusuario_id\u001f,\u001fpaciente_id\u001f,\u001fcreado_en\u001f)\u001fCREATE\u001fINDEX\u001fnotas_patient\u001fON\u001fmymind\u001f.\u001fnotas_clinicas\u001f(\u001fusuario_id\u001f,\u001fpaciente_id\u001f,\u001fcreado_en\u001fDESC\u001f)\u001fCREATE\u001fINDEX\u001feventos_patient\u001fON\u001fmymind\u001f.\u001fatencion_eventos\u001f(\u001fusuario_id\u001f,\u001fpaciente_id\u001f,\u001fid\u001fDESC\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fnota_ciclo_vida\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''Clinical notes cannot be deleted'' USING ERRCODE=''23514''; END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF OLD.estado=''finalizada'' THEN RAISE EXCEPTION ''Finalized note is immutable; append an addendum'' USING ERRCODE=''23514''; END IF;\n  IF (NEW.id,NEW.paciente_id,NEW.usuario_id,NEW.sesion_id,NEW.creado_en,NEW.creado_por) IS DISTINCT FROM (OLD.id,OLD.paciente_id,OLD.usuario_id,OLD.sesion_id,OLD.creado_en,OLD.creado_por) THEN RAISE EXCEPTION ''Note identity is immutable'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=OLD.version+1;\n ELSE\n  IF NEW.estado<>''borrador'' THEN RAISE EXCEPTION ''Create a draft first'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=1; NEW.creado_en:=now();\n END IF;\n NEW.actualizado_en:=now();\n IF NEW.actualizado_por<>NEW.usuario_id OR NEW.creado_por<>NEW.usuario_id THEN RAISE EXCEPTION ''Note author must own the patient'' USING ERRCODE=''23514''; END IF;\n IF NEW.estado=''finalizada'' THEN\n  PERFORM 1 FROM sesiones WHERE id=NEW.sesion_id AND paciente_id=NEW.paciente_id AND estado_sesion=''Realizada'' AND fecha_hora::timestamptz<=now() FOR UPDATE;\n  IF NOT FOUND OR coalesce(trim(NEW.contenido->>''resumen''),'''')='''' THEN RAISE EXCEPTION ''Finalization requires a completed session and summary'' USING ERRCODE=''23514''; END IF;\n  NEW.finalizada_en:=now(); NEW.finalizada_por:=NEW.actualizado_por;\n END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fnota_ciclo_vida\u001fBEFORE\u001fINSERT\u001fOR\u001fUPDATE\u001fOR\u001fDELETE\u001fON\u001fmymind\u001f.\u001fnotas_clinicas\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fnota_ciclo_vida\u001f(\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fnota_guardar_revision\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n INSERT INTO nota_revisiones(nota_id,version,contenido,estado,autor_id) VALUES(NEW.id,NEW.version,NEW.contenido,NEW.estado,NEW.actualizado_por);\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fnota_revision\u001fAFTER\u001fINSERT\u001fOR\u001fUPDATE\u001fON\u001fmymind\u001f.\u001fnotas_clinicas\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fnota_guardar_revision\u001f(\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fhistorial_inmutable\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fAS\u001f$$\nBEGIN RAISE EXCEPTION ''Append-only clinical history'' USING ERRCODE=''23514''; END $$\u001fCREATE\u001fTRIGGER\u001frevisiones_inmutables\u001fBEFORE\u001fUPDATE\u001fOR\u001fDELETE\u001fON\u001fmymind\u001f.\u001fnota_revisiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fhistorial_inmutable\u001f(\u001f)\u001fCREATE\u001fTRIGGER\u001fadendas_inmutables\u001fBEFORE\u001fUPDATE\u001fOR\u001fDELETE\u001fON\u001fmymind\u001f.\u001fnota_adendas\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fhistorial_inmutable\u001f(\u001f)\u001fCREATE\u001fTRIGGER\u001feventos_inmutables\u001fBEFORE\u001fUPDATE\u001fOR\u001fDELETE\u001fON\u001fmymind\u001f.\u001fatencion_eventos\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fhistorial_inmutable\u001f(\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fvalidar_adenda\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM notas_clinicas WHERE id=NEW.nota_id AND estado=''finalizada'' AND usuario_id=NEW.autor_id) THEN RAISE EXCEPTION ''Addendum requires a finalized note owned by its author'' USING ERRCODE=''23514''; END IF;\n NEW.registrado_en:=now(); RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fadenda_validar\u001fBEFORE\u001fINSERT\u001fON\u001fmymind\u001f.\u001fnota_adendas\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fvalidar_adenda\u001f(\u001f)\u001fDO\u001f$$ DECLARE t text; r text; BEGIN\n FOREACH t IN ARRAY ARRAY[''fichas_atencion'',''objetivos_terapeuticos'',''notas_clinicas'',''nota_revisiones'',''nota_adendas'',''atencion_eventos''] LOOP\n  EXECUTE format(''ALTER TABLE mymind.%I ENABLE ROW LEVEL SECURITY'',t);\n  EXECUTE format(''REVOKE ALL ON mymind.%I FROM PUBLIC'',t);\n  FOREACH r IN ARRAY ARRAY[''anon'',''authenticated''] LOOP\n   IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format(''REVOKE ALL ON mymind.%I FROM %I'',t,r); END IF;\n  END LOOP;\n END LOOP;\nEND $$\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fsesion_finalizada_inmutable\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF (NEW.paciente_id,NEW.fecha_hora,NEW.duracion_minutos,NEW.modalidad,NEW.estado_sesion) IS DISTINCT FROM (OLD.paciente_id,OLD.fecha_hora,OLD.duracion_minutos,OLD.modalidad,OLD.estado_sesion) AND EXISTS(SELECT 1 FROM notas_clinicas WHERE sesion_id=OLD.id AND estado=''finalizada'') THEN RAISE EXCEPTION ''Session has a finalized clinical note'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fsesion_finalizada_inmutable\u001fBEFORE\u001fUPDATE\u001fON\u001fmymind\u001f.\u001fsesiones\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fsesion_finalizada_inmutable\u001f(\u001f)\u001fCREATE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_trazabilidad\u001f(\u001f)\u001fRETURNS\u001ftrigger\u001fLANGUAGE\u001fplpgsql\u001fSET\u001fsearch_path\u001f=\u001fmymind\u001f,\u001fpg_temp\u001fAS\u001f$$\nBEGIN\n IF (NEW.motivo_consulta,NEW.antecedentes,NEW.hipotesis_diagnostica,NEW.notas_confidenciales) IS DISTINCT FROM (OLD.motivo_consulta,OLD.antecedentes,OLD.hipotesis_diagnostica,OLD.notas_confidenciales) THEN\n INSERT INTO atencion_eventos(paciente_id,usuario_id,actor_id,accion,recurso_id,version) VALUES(NEW.id,NEW.usuario_id,NEW.usuario_id,''expediente_actualizado'',NEW.id,NEW.expediente_version);\n END IF; RETURN NEW;\nEND $$\u001fCREATE\u001fTRIGGER\u001fexpediente_trazabilidad\u001fAFTER\u001fUPDATE\u001fON\u001fmymind\u001f.\u001fpacientes\u001fFOR\u001fEACH\u001fROW\u001fEXECUTE\u001fFUNCTION\u001fmymind\u001f.\u001fexpediente_trazabilidad\u001f(\u001f)","contract":[["column:fichas_atencion.paciente_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:fichas_atencion.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:fichas_atencion.datos","{\"type\": \"jsonb\", \"default\": \"''{}''::jsonb\", \"required\": true}"],["column:fichas_atencion.version","{\"type\": \"integer\", \"default\": \"1\", \"required\": true}"],["column:fichas_atencion.actualizado_por","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:fichas_atencion.actualizado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:objetivos_terapeuticos.id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:objetivos_terapeuticos.paciente_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:objetivos_terapeuticos.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:objetivos_terapeuticos.titulo","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:objetivos_terapeuticos.descripcion","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:objetivos_terapeuticos.criterio_logro","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:objetivos_terapeuticos.estado","{\"type\": \"text\", \"default\": \"''activo''::text\", \"required\": true}"],["column:objetivos_terapeuticos.fecha_revision","{\"type\": \"date\", \"default\": null, \"required\": false}"],["column:objetivos_terapeuticos.version","{\"type\": \"integer\", \"default\": \"1\", \"required\": true}"],["column:objetivos_terapeuticos.creado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:objetivos_terapeuticos.actualizado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:objetivos_terapeuticos.actualizado_por","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.paciente_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.sesion_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.contenido","{\"type\": \"jsonb\", \"default\": null, \"required\": true}"],["column:notas_clinicas.estado","{\"type\": \"text\", \"default\": \"''borrador''::text\", \"required\": true}"],["column:notas_clinicas.version","{\"type\": \"integer\", \"default\": \"1\", \"required\": true}"],["column:notas_clinicas.creado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:notas_clinicas.actualizado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:notas_clinicas.creado_por","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.actualizado_por","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:notas_clinicas.finalizada_en","{\"type\": \"timestamp with time zone\", \"default\": null, \"required\": false}"],["column:notas_clinicas.finalizada_por","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:nota_revisiones.nota_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_revisiones.version","{\"type\": \"integer\", \"default\": null, \"required\": true}"],["column:nota_revisiones.contenido","{\"type\": \"jsonb\", \"default\": null, \"required\": true}"],["column:nota_revisiones.estado","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_revisiones.autor_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_revisiones.registrado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:nota_adendas.id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_adendas.nota_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_adendas.texto","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_adendas.autor_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:nota_adendas.registrado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["column:atencion_eventos.id","{\"type\": \"bigint\", \"default\": null, \"required\": true}"],["column:atencion_eventos.paciente_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:atencion_eventos.usuario_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:atencion_eventos.actor_id","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:atencion_eventos.accion","{\"type\": \"text\", \"default\": null, \"required\": true}"],["column:atencion_eventos.recurso_id","{\"type\": \"text\", \"default\": null, \"required\": false}"],["column:atencion_eventos.version","{\"type\": \"integer\", \"default\": null, \"required\": false}"],["column:atencion_eventos.registrado_en","{\"type\": \"timestamp with time zone\", \"default\": \"now()\", \"required\": true}"],["constraint:notas_clinicas:FOREIGN KEY (creado_por) REFERENCES mymind.usuarios(id)","present"],["constraint:fichas_atencion:CHECK ((jsonb_typeof(datos) = ''object''::text))","present"],["constraint:fichas_atencion:CHECK ((version > 0))","present"],["constraint:fichas_atencion:PRIMARY KEY (paciente_id)","present"],["constraint:fichas_atencion:FOREIGN KEY (actualizado_por) REFERENCES mymind.usuarios(id)","present"],["constraint:fichas_atencion:FOREIGN KEY (paciente_id, usuario_id) REFERENCES mymind.pacientes(id, usuario_id) ON DELETE RESTRICT","present"],["constraint:objetivos_terapeuticos:CHECK (((length(TRIM(BOTH FROM titulo)) >= 1) AND (length(TRIM(BOTH FROM titulo)) <= 300)))","present"],["constraint:objetivos_terapeuticos:CHECK ((estado = ANY (ARRAY[''activo''::text, ''logrado''::text, ''pausado''::text])))","present"],["constraint:notas_clinicas:FOREIGN KEY (actualizado_por) REFERENCES mymind.usuarios(id)","present"],["constraint:notas_clinicas:FOREIGN KEY (finalizada_por) REFERENCES mymind.usuarios(id)","present"],["constraint:notas_clinicas:FOREIGN KEY (paciente_id, usuario_id) REFERENCES mymind.pacientes(id, usuario_id) ON DELETE RESTRICT","present"],["constraint:notas_clinicas:FOREIGN KEY (sesion_id, paciente_id) REFERENCES mymind.sesiones(id, paciente_id) ON DELETE RESTRICT","present"],["constraint:objetivos_terapeuticos:CHECK ((version > 0))","present"],["constraint:objetivos_terapeuticos:PRIMARY KEY (id)","present"],["constraint:objetivos_terapeuticos:FOREIGN KEY (actualizado_por) REFERENCES mymind.usuarios(id)","present"],["constraint:objetivos_terapeuticos:FOREIGN KEY (paciente_id, usuario_id) REFERENCES mymind.pacientes(id, usuario_id) ON DELETE RESTRICT","present"],["constraint:notas_clinicas:CHECK ((jsonb_typeof(contenido) = ''object''::text))","present"],["constraint:notas_clinicas:CHECK ((estado = ANY (ARRAY[''borrador''::text, ''finalizada''::text])))","present"],["constraint:notas_clinicas:CHECK ((version > 0))","present"],["constraint:notas_clinicas:CHECK ((((estado = ''borrador''::text) AND (finalizada_en IS NULL) AND (finalizada_por IS NULL)) OR ((estado = ''finalizada''::text) AND (finalizada_en IS NOT NULL) AND (finalizada_por IS NOT NULL))))","present"],["constraint:notas_clinicas:PRIMARY KEY (id)","present"],["constraint:notas_clinicas:UNIQUE (sesion_id)","present"],["constraint:nota_revisiones:PRIMARY KEY (nota_id, version)","present"],["constraint:nota_revisiones:FOREIGN KEY (nota_id) REFERENCES mymind.notas_clinicas(id) ON DELETE RESTRICT","present"],["constraint:nota_revisiones:FOREIGN KEY (autor_id) REFERENCES mymind.usuarios(id)","present"],["constraint:nota_adendas:CHECK (((length(TRIM(BOTH FROM texto)) >= 1) AND (length(TRIM(BOTH FROM texto)) <= 10000)))","present"],["constraint:nota_adendas:PRIMARY KEY (id)","present"],["constraint:nota_adendas:FOREIGN KEY (nota_id) REFERENCES mymind.notas_clinicas(id) ON DELETE RESTRICT","present"],["constraint:nota_adendas:FOREIGN KEY (autor_id) REFERENCES mymind.usuarios(id)","present"],["constraint:atencion_eventos:PRIMARY KEY (id)","present"],["constraint:atencion_eventos:FOREIGN KEY (actor_id) REFERENCES mymind.usuarios(id)","present"],["constraint:atencion_eventos:FOREIGN KEY (paciente_id, usuario_id) REFERENCES mymind.pacientes(id, usuario_id) ON DELETE RESTRICT","present"],["table:fichas_atencion","{\"rls\": true, \"force\": false}"],["table:objetivos_terapeuticos","{\"rls\": true, \"force\": false}"],["table:notas_clinicas","{\"rls\": true, \"force\": false}"],["table:nota_revisiones","{\"rls\": true, \"force\": false}"],["table:nota_adendas","{\"rls\": true, \"force\": false}"],["table:atencion_eventos","{\"rls\": true, \"force\": false}"],["function:nota_ciclo_vida()","CREATE OR REPLACE FUNCTION mymind.nota_ciclo_vida()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n IF TG_OP=''DELETE'' THEN RAISE EXCEPTION ''Clinical notes cannot be deleted'' USING ERRCODE=''23514''; END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF OLD.estado=''finalizada'' THEN RAISE EXCEPTION ''Finalized note is immutable; append an addendum'' USING ERRCODE=''23514''; END IF;\n  IF (NEW.id,NEW.paciente_id,NEW.usuario_id,NEW.sesion_id,NEW.creado_en,NEW.creado_por) IS DISTINCT FROM (OLD.id,OLD.paciente_id,OLD.usuario_id,OLD.sesion_id,OLD.creado_en,OLD.creado_por) THEN RAISE EXCEPTION ''Note identity is immutable'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=OLD.version+1;\n ELSE\n  IF NEW.estado<>''borrador'' THEN RAISE EXCEPTION ''Create a draft first'' USING ERRCODE=''23514''; END IF;\n  NEW.version:=1; NEW.creado_en:=now();\n END IF;\n NEW.actualizado_en:=now();\n IF NEW.actualizado_por<>NEW.usuario_id OR NEW.creado_por<>NEW.usuario_id THEN RAISE EXCEPTION ''Note author must own the patient'' USING ERRCODE=''23514''; END IF;\n IF NEW.estado=''finalizada'' THEN\n  PERFORM 1 FROM sesiones WHERE id=NEW.sesion_id AND paciente_id=NEW.paciente_id AND estado_sesion=''Realizada'' AND fecha_hora::timestamptz<=now() FOR UPDATE;\n  IF NOT FOUND OR coalesce(trim(NEW.contenido->>''resumen''),'''')='''' THEN RAISE EXCEPTION ''Finalization requires a completed session and summary'' USING ERRCODE=''23514''; END IF;\n  NEW.finalizada_en:=now(); NEW.finalizada_por:=NEW.actualizado_por;\n END IF;\n RETURN NEW;\nEND $function$\n"],["function:nota_guardar_revision()","CREATE OR REPLACE FUNCTION mymind.nota_guardar_revision()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n INSERT INTO nota_revisiones(nota_id,version,contenido,estado,autor_id) VALUES(NEW.id,NEW.version,NEW.contenido,NEW.estado,NEW.actualizado_por);\n RETURN NEW;\nEND $function$\n"],["function:historial_inmutable()","CREATE OR REPLACE FUNCTION mymind.historial_inmutable()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN RAISE EXCEPTION ''Append-only clinical history'' USING ERRCODE=''23514''; END $function$\n"],["function:validar_adenda()","CREATE OR REPLACE FUNCTION mymind.validar_adenda()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n IF NOT EXISTS(SELECT 1 FROM notas_clinicas WHERE id=NEW.nota_id AND estado=''finalizada'' AND usuario_id=NEW.autor_id) THEN RAISE EXCEPTION ''Addendum requires a finalized note owned by its author'' USING ERRCODE=''23514''; END IF;\n NEW.registrado_en:=now(); RETURN NEW;\nEND $function$\n"],["function:sesion_finalizada_inmutable()","CREATE OR REPLACE FUNCTION mymind.sesion_finalizada_inmutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n IF (NEW.paciente_id,NEW.fecha_hora,NEW.duracion_minutos,NEW.modalidad,NEW.estado_sesion) IS DISTINCT FROM (OLD.paciente_id,OLD.fecha_hora,OLD.duracion_minutos,OLD.modalidad,OLD.estado_sesion) AND EXISTS(SELECT 1 FROM notas_clinicas WHERE sesion_id=OLD.id AND estado=''finalizada'') THEN RAISE EXCEPTION ''Session has a finalized clinical note'' USING ERRCODE=''23514''; END IF;\n RETURN NEW;\nEND $function$\n"],["function:expediente_trazabilidad()","CREATE OR REPLACE FUNCTION mymind.expediente_trazabilidad()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''mymind'', ''pg_temp''\nAS $function$\nBEGIN\n IF (NEW.motivo_consulta,NEW.antecedentes,NEW.hipotesis_diagnostica,NEW.notas_confidenciales) IS DISTINCT FROM (OLD.motivo_consulta,OLD.antecedentes,OLD.hipotesis_diagnostica,OLD.notas_confidenciales) THEN\n INSERT INTO atencion_eventos(paciente_id,usuario_id,actor_id,accion,recurso_id,version) VALUES(NEW.id,NEW.usuario_id,NEW.usuario_id,''expediente_actualizado'',NEW.id,NEW.expediente_version);\n END IF; RETURN NEW;\nEND $function$\n"],["trigger:sesiones.sesion_finalizada_inmutable","CREATE TRIGGER sesion_finalizada_inmutable BEFORE UPDATE ON mymind.sesiones FOR EACH ROW EXECUTE FUNCTION mymind.sesion_finalizada_inmutable()"],["trigger:pacientes.expediente_trazabilidad","CREATE TRIGGER expediente_trazabilidad AFTER UPDATE ON mymind.pacientes FOR EACH ROW EXECUTE FUNCTION mymind.expediente_trazabilidad()"],["trigger:notas_clinicas.nota_revision","CREATE TRIGGER nota_revision AFTER INSERT OR UPDATE ON mymind.notas_clinicas FOR EACH ROW EXECUTE FUNCTION mymind.nota_guardar_revision()"],["trigger:notas_clinicas.nota_ciclo_vida","CREATE TRIGGER nota_ciclo_vida BEFORE INSERT OR DELETE OR UPDATE ON mymind.notas_clinicas FOR EACH ROW EXECUTE FUNCTION mymind.nota_ciclo_vida()"],["trigger:nota_revisiones.revisiones_inmutables","CREATE TRIGGER revisiones_inmutables BEFORE DELETE OR UPDATE ON mymind.nota_revisiones FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable()"],["trigger:nota_adendas.adenda_validar","CREATE TRIGGER adenda_validar BEFORE INSERT ON mymind.nota_adendas FOR EACH ROW EXECUTE FUNCTION mymind.validar_adenda()"],["trigger:nota_adendas.adendas_inmutables","CREATE TRIGGER adendas_inmutables BEFORE DELETE OR UPDATE ON mymind.nota_adendas FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable()"],["trigger:atencion_eventos.eventos_inmutables","CREATE TRIGGER eventos_inmutables BEFORE DELETE OR UPDATE ON mymind.atencion_eventos FOR EACH ROW EXECUTE FUNCTION mymind.historial_inmutable()"],["index:notas_patient","CREATE INDEX notas_patient ON mymind.notas_clinicas USING btree (usuario_id, paciente_id, creado_en DESC)"],["index:eventos_patient","CREATE INDEX eventos_patient ON mymind.atencion_eventos USING btree (usuario_id, paciente_id, id DESC)"],["index:objetivos_patient","CREATE INDEX objetivos_patient ON mymind.objetivos_terapeuticos USING btree (usuario_id, paciente_id, creado_en)"]]}]'::jsonb; f jsonb; pair jsonb; old_checksum text; cli record; actual text; latest jsonb:='{}'::jsonb; adopted integer:=0;
BEGIN
 IF to_regclass('mymind.schema_migrations') IS NULL OR to_regclass('supabase_migrations.schema_migrations') IS NULL THEN RAISE EXCEPTION 'Both existing ledgers are required. Use db:migrate for a fresh database.'; END IF;
 IF EXISTS(SELECT 1 FROM mymind.schema_migrations a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) x WHERE x->>'name'=a.name)) OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) x WHERE x->>'version'=a.version)) THEN RAISE EXCEPTION 'Database contains migrations missing from this repository snapshot'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(manifest) LOOP
   SELECT checksum INTO old_checksum FROM mymind.schema_migrations WHERE name=f->>'name';
   IF old_checksum IS NOT NULL AND old_checksum<>f->>'checksum' AND (old_checksum IS DISTINCT FROM f->>'legacy' OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=f->>'version')) THEN RAISE EXCEPTION 'App checksum differs: %',f->>'name'; END IF;
   SELECT * INTO cli FROM supabase_migrations.schema_migrations WHERE version=f->>'version';
   IF FOUND AND (cli.name IS DISTINCT FROM f->>'label' OR pg_temp.migration_tokens(array_to_string(cli.statements,E';\n')) IS DISTINCT FROM f->>'tokens') THEN RAISE EXCEPTION 'Supabase SQL differs: %',f->>'name'; END IF;
   IF old_checksum IS NOT NULL OR cli.version IS NOT NULL THEN
     FOR pair IN SELECT * FROM jsonb_array_elements(f->'contract') LOOP latest:=latest||jsonb_build_object(pair->>0,pair->>1); END LOOP;
   END IF;
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(manifest) LOOP
   IF (NOT EXISTS(SELECT 1 FROM mymind.schema_migrations WHERE name=f->>'name') OR EXISTS(SELECT 1 FROM mymind.schema_migrations WHERE name=f->>'name' AND checksum<>f->>'checksum')) AND EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=f->>'version') THEN
     FOR pair IN SELECT * FROM jsonb_array_elements(f->'contract') LOOP
       SELECT value INTO actual FROM (
SELECT 'column:'||c.relname||'.'||a.attname AS key,
 jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'required',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))::text AS value
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped
 LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
 WHERE n.nspname='mymind' AND c.relkind='r' AND c.relname<>'schema_migrations'
UNION ALL
 SELECT 'constraint:'||c.relname||':'||pg_get_constraintdef(k.oid), 'present'
 FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='mymind' AND c.relname<>'schema_migrations' AND k.contype<>'n'
UNION ALL
 SELECT 'table:'||c.relname, jsonb_build_object('rls',c.relrowsecurity,'force',c.relforcerowsecurity)::text
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='mymind' AND c.relkind='r' AND c.relname<>'schema_migrations'
UNION ALL
 SELECT 'function:'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',replace(pg_get_functiondef(p.oid),chr(13)||chr(10),chr(10))
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='mymind'
UNION ALL
 SELECT 'trigger:'||c.relname||'.'||t.tgname, pg_get_triggerdef(t.oid)
 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='mymind' AND NOT t.tgisinternal
UNION ALL
 SELECT 'index:'||i.indexname, i.indexdef FROM pg_indexes i
 WHERE i.schemaname='mymind' AND NOT EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=(quote_ident(i.schemaname)||'.'||quote_ident(i.indexname))::regclass)
) catalog WHERE key=pair->>0;
       IF actual IS DISTINCT FROM latest->>(pair->>0) THEN RAISE EXCEPTION 'Schema differs for %: %',f->>'name',split_part(pair->>0,':',1)||':'||split_part(pair->>0,':',2); END IF;
     END LOOP;
     IF EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='mymind' AND tablename IN ('agenda_emails','evaluaciones_clinicas')) THEN RAISE EXCEPTION 'Unexpected access policy on private application table'; END IF;
     SELECT checksum INTO old_checksum FROM mymind.schema_migrations WHERE name=f->>'name';
     IF old_checksum IS NOT NULL THEN
       CREATE TABLE IF NOT EXISTS mymind.migration_reconciliation_audit(name text NOT NULL,old_checksum text NOT NULL,new_checksum text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(name,old_checksum,new_checksum));
       ALTER TABLE mymind.migration_reconciliation_audit ENABLE ROW LEVEL SECURITY;
       REVOKE ALL ON mymind.migration_reconciliation_audit FROM PUBLIC;
       INSERT INTO mymind.migration_reconciliation_audit(name,old_checksum,new_checksum) VALUES(f->>'name',old_checksum,f->>'checksum') ON CONFLICT DO NOTHING;
       UPDATE mymind.schema_migrations SET checksum=f->>'checksum' WHERE name=f->>'name';
     ELSE INSERT INTO mymind.schema_migrations(name,checksum) VALUES(f->>'name',f->>'checksum'); END IF;
     adopted:=adopted+1;
   END IF;
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(manifest) LOOP
   IF EXISTS(SELECT 1 FROM mymind.schema_migrations WHERE name=f->>'name') THEN
     INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES(f->>'version',f->>'label',ARRAY[f->>'sql']) ON CONFLICT(version) DO NOTHING;
   END IF;
 END LOOP;
 RAISE NOTICE 'Verified and reconciled % migrations. No clinical records changed.',adopted;
END $reconcile$;
COMMIT;
SELECT name,checksum FROM mymind.schema_migrations ORDER BY name;
